#!/usr/bin/env node
// cyrus.my landing: the "Featured mods" section, generated into dist/index.html at build time (plain Node, no deps).
//   node featured.mjs --in dist/index.html --json <file|https-url> [--out <file>] [--origin <url: link titles to the community page; default none>]
// The JSON is the public list the app serves at /api/cyrus/featured ({ cards: [...] }, public + moderated mods only).
// The section replaces whatever sits between the markers in the page; an empty list or an unreadable source leaves the
// markers EMPTY (the section simply is not there). Every value is HTML-escaped; links are built here, never taken from data.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

export const START = "<!-- featured-mods:start -->";
export const END = "<!-- featured-mods:end -->";
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const slugOk = (s) => typeof s === "string" && /^[a-z0-9][a-z0-9-]{0,80}$/.test(s);

const CSS = `<style>
#featured .fm-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px}
#featured .fm-card{display:flex;flex-direction:column;gap:12px;padding:20px;border:1px solid var(--line-2);border-radius:var(--r);background:var(--glass)}
#featured .fm-card h3{margin:0;font-size:18px;line-height:1.25}
#featured .fm-by,#featured .fm-meta{margin:0;color:var(--ink-3);font-size:13px}
#featured .fm-tag{margin:0;color:var(--ink-2);font-size:14.5px}
#featured .fm-foot{margin-top:auto;display:flex;flex-wrap:wrap;align-items:center;gap:12px}
#featured .fm-rate{color:var(--ink-2);font-size:13px}
#featured .fm-foot .btn{margin-left:auto}
@media (max-width:560px){#featured .fm-grid{grid-template-columns:1fr}}
</style>`;

/** The section HTML for a list of public cards ("" for none). */
export function renderFeaturedSection(cards, { origin = "", makeBase = "/new" } = {}) {
  const list = (Array.isArray(cards) ? cards : []).filter((c) => c && slugOk(c.slug) && typeof c.title === "string" && c.title.trim()).slice(0, 12);
  if (!list.length) return "";
  // No origin (the default): community pages are not served on cyrus.my, so the title is plain text and nothing on the
  // landing points at nxeon.cloud. An explicit --origin opts a link back in.
  const base = String(origin || "").replace(/\/+$/, "");
  const items = list.map((c) => {
    const rating = typeof c.rating === "number" && c.rating > 0 ? `${c.rating.toFixed(1)} / 5 (${Number(c.ratings) || 0})` : "New";
    const meta = [c.game || "Minecraft", c.gameVersion, c.version ? `v${String(c.version).replace(/^v/i, "")}` : ""].filter(Boolean).map(esc).join(" · ");
    return `      <article class="fm-card reveal">
        <div><h3>${base ? `<a href="${esc(base)}/mods/cyrus/${esc(c.slug)}" rel="noopener">${esc(c.title)}</a>` : esc(c.title)}</h3><p class="fm-by">by ${esc(c.creator || "a Cyrus creator")}</p></div>
        <p class="fm-meta">${meta}</p>
        ${c.tagline ? `<p class="fm-tag">${esc(String(c.tagline).slice(0, 160))}</p>` : ""}

// Cyrus USERNAME: DB side (claim, change, availability, author-tag lookups). Rules live in ./username.ts.
import { randomBytes } from "node:crypto";
import { cyrusDb } from "../cyrus/db";
import { UNNAMED_AUTHOR, holdUntil, mayChangeUsername, validateUsername } from "./username";

export type UsernameState = { username: string | null; usernameKey: string | null; handle: string | null; setAt: string | null; canChange: boolean; nextChangeAt: string | null };

export async function usernameStateFor(userId: string): Promise<UsernameState> {
  const c = await cyrusDb.cyrusCreator.findUnique({ where: { userId } });
  const d = mayChangeUsername(c?.usernameSetAt ?? null);
  return { username: c?.username ?? null, usernameKey: c?.usernameKey ?? null, handle: c?.handle ?? null, setAt: c?.usernameSetAt?.toISOString() ?? null, canChange: d.ok, nextChangeAt: d.ok ? null : d.nextAt };
}

/** Has this account chosen its author tag? (the first-run gate). */
export async function hasUsername(userId: string): Promise<boolean> {
  const c = await cyrusDb.cyrusCreator.findUnique({ where: { userId }, select: { usernameKey: true } });
  return !!c?.usernameKey;
}

export type Availability = { ok: true; display: string; key: string } | { ok: false; message: string; code: string };

/** Valid AND free for this account (own current name counts as free; a hold by someone else blocks it). */
export async function checkAvailability(raw: unknown, forUserId: string | null): Promise<Availability> {
  const v = validateUsername(raw);
  if (!v.ok) return { ok: false, code: v.code, message: v.message };
  const [creator, handleOwner, hold] = await Promise.all([
    cyrusDb.cyrusCreator.findUnique({ where: { usernameKey: v.key }, select: { userId: true } }),
    cyrusDb.cyrusCreator.findUnique({ where: { handle: v.key }, select: { userId: true } }),
    cyrusDb.cyrusUsernameHold.findUnique({ where: { usernameKey: v.key } }),
  ]);
  if (creator && creator.userId !== forUserId) return { ok: false, code: "taken", message: "That username is taken." };
  if (handleOwner && handleOwner.userId !== forUserId) return { ok: false, code: "taken", message: "That username is taken." };
  if (hold && hold.reservedUntil > new Date() && hold.userId !== forUserId) return { ok: false, code: "held", message: "That username is not available." };
  return { ok: true, display: v.display, key: v.key };
}

export type SetResult = { ok: true; username: string } | { ok: false; code: string; message: string };

/** Claim (first time) or change the username. The unique index is the final arbiter; a lost race reads as "taken". */
export async function setUsername(userId: string, raw: unknown): Promise<SetResult> {
  const a = await checkAvailability(raw, userId);
  if (!a.ok) return a;
  const cur = await cyrusDb.cyrusCreator.findUnique({ where: { userId } });
  if (cur?.usernameKey === a.key) {
    // same name, maybe a case change: allowed any time, no hold, no wait
    if (cur.username !== a.display) await cyrusDb.cyrusCreator.update({ where: { userId }, data: { username: a.display } });
    return { ok: true, username: a.display };
  }
  const gate = mayChangeUsername(cur?.usernameSetAt ?? null);
  if (!gate.ok) return { ok: false, code: "too-soon", message: gate.message };
  const now = new Date();
  try {
    await cyrusDb.$transaction(async (tx) => {
      if (cur?.usernameKey) {
        await tx.cyrusUsernameHold.upsert({ where: { usernameKey: cur.usernameKey }, create: { usernameKey: cur.usernameKey, userId, releasedAt: now, reservedUntil: holdUntil(now) }, update: { userId, releasedAt: now, reservedUntil: holdUntil(now) } });
      }
      // taking a name this account itself released earlier: drop its own hold
      await tx.cyrusUsernameHold.deleteMany({ where: { usernameKey: a.key, userId } });
      if (cur) await tx.cyrusCreator.update({ where: { userId }, data: { username: a.display, usernameKey: a.key, usernameSetAt: now, handle: a.key } });
      else await tx.cyrusCreator.create({ data: { userId, handle: a.key, username: a.display, usernameKey: a.key, usernameSetAt: now } });
    });
  } catch {
    return { ok: false, code: "taken", message: "That username was just taken. Try another." };
  }
  return { ok: true, username: a.display };
}

/** userId -> public author tag. Accounts without a tag get the generic label, NEVER the account name. */
export async function authorTags(userIds: string[]): Promise<Map<string, string>> {
  const ids = [...new Set(userIds)];
  const out = new Map<string, string>();
  if (!ids.length) return out;
  const rows = await cyrusDb.cyrusCreator.findMany({ where: { userId: { in: ids } }, select: { userId: true, username: true } }).catch(() => []);
  for (const r of rows) if (r.username) out.set(r.userId, r.username);
  for (const id of ids) if (!out.has(id)) out.set(id, UNNAMED_AUTHOR);
  return out;
}

export async function authorTagOf(userId: string): Promise<string> {
  return (await authorTags([userId])).get(userId) ?? UNNAMED_AUTHOR;
}

/** A suggestion that is free right now (never the account name): "maker-4f2a". */
export async function suggestUsername(): Promise<string> {
  for (let i = 0; i < 5; i++) {
    const s = `maker-${randomBytes(2).toString("hex")}`;
    if ((await checkAvailability(s, null)).ok) return s;
  }
  return `maker-${randomBytes(4).toString("hex")}`;
}

/** Drop-in for `db.user.findMany({select:{id,name}})` on PUBLIC surfaces: `name` is the author tag, never the account name. */
export async function authorUsers(userIds: string[]): Promise<{ id: string; name: string }[]> {
  const m = await authorTags(userIds);
  return [...m].map(([id, name]) => ({ id, name }));
}
/** Drop-in for `db.user.findUnique({select:{name}})` on public surfaces. */
export async function authorUser(userId: string): Promise<{ name: string }> {
  return { name: await authorTagOf(userId) };
}
// Cyrus USERNAME (author tag): the pure rules. No DB, no Nxeon imports (unit-tested in test/cyrus-username.test.ts).
//
// What it is: the name an account picks the first time it opens Cyrus (Nxeon portal or cyrus.my). It is the AUTHOR TAG
// shown on every public mod page, listing, creator profile, download README/LICENSE and SEO markup, instead of the
// personal name on the Nxeon account (which is never shown publicly any more).
//
// Policy (the documented decisions):
//   - 3-20 characters, [a-z0-9_-] after lowercasing; must start and end with a letter or digit; no "--"/"__" runs.
//   - Unique case-insensitively (usernameKey = lowercase form, plain unique index). The display case the user typed is kept.
//   - Reserved words, brand/staff impersonation, and a profanity list are refused (also after leetspeak folding and
//     with separators removed: "n_x_e_o_n", "cyr0s", "adm1n" are all refused).
//   - Change policy: allowed once per 30 days. The released name is held for its previous owner for 90 days (CyrusUsernameHold)
//     so it cannot be sniped or used to pose as the account that used it. Old public profile URLs follow the new name.
//   - First choice is free of the 30-day wait.

export const USERNAME_MIN = 3;
export const USERNAME_MAX = 20;
export const USERNAME_CHANGE_DAYS = 30;
export const USERNAME_HOLD_DAYS = 90;
/** The generic public label for an account that has not chosen a tag yet (never the personal name). */
export const UNNAMED_AUTHOR = "Cyrus creator";

const SHAPE = /^[a-z0-9](?:[a-z0-9_-]{1,18})[a-z0-9]$/;

/** Words that can never be a username (exact match after folding). */
const RESERVED = new Set([
  "nxeon", "nexion", "cyrus", "cyrusmy", "cyrusai", "nxlabs", "nxm", "admin", "administrator", "root", "system", "sys",
  "staff", "support", "help", "mod", "mods", "moderator", "modteam", "official", "team", "security", "billing", "abuse",
  "postmaster", "webmaster", "hostmaster", "noreply", "noreplies", "info", "contact", "sales", "legal", "privacy", "terms",
  "api", "app", "www", "web", "mail", "dev", "dev-team", "null", "undefined", "anonymous", "everyone", "here", "channel",
  "minecraft", "mojang", "microsoft", "anthropic", "claude", "openai", "paper", "papermc", "spigot", "bukkit", "purpur",
  "me", "you", "user", "users", "account", "login", "logout", "register", "signup", "signin", "settings", "profile",
  "u", "c", "new", "edit", "delete", "create", "community", "library", "download", "install", "featured", "spotlight",
]);

/** Brand / authority words that may not appear INSIDE a name (impersonation): "nxeon_support", "realcyrus", "adminbob". */
const IMPERSONATION = ["nxeon", "nexion", "cyrus", "official", "staff", "support", "admin", "moderator", "mojang", "microsoft", "anthropic", "paperteam", "teamnx"];

/** A deliberately small, conservative profanity/hate blocklist matched on the folded, separator-free form. */
const BLOCKED = [
  "fuck", "shit", "cunt", "bitch", "nigg", "fagg", "retard", "whore", "slut", "rapist", "nazi", "hitler", "pedo", "paedo",
  "cocksuck", "dickhead", "asshole", "bastard", "jihad", "killall",
];
/** Short words that are also inside innocent ones ("grape", "crisis", "essex"): refused only as a whole part of the name (or its start). */
const BLOCKED_EDGE = ["rape", "porn", "sex", "kkk", "isis", "suicide"];

/** Fold look-alikes so "cyr0s"/"adm1n"/"n3xion" cannot slip past: digits and symbols that stand in for letters. */
export function foldForChecks(s: string): string {
  const map: Record<string, string> = { "0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "8": "b", "9": "g", "$": "s", "@": "a", "!": "i" };
  return s.toLowerCase().replace(/[01345789$@!]/g, (c) => map[c] ?? c).replace(/[^a-z]/g, "");
}

export type UsernameVerdict =
  | { ok: true; display: string; key: string }
  | { ok: false; code: "empty" | "length" | "chars" | "edges" | "runs" | "reserved" | "impersonation" | "blocked"; message: string };

export function validateUsername(raw: unknown): UsernameVerdict {
  const display = typeof raw === "string" ? raw.trim() : "";
  if (!display) return { ok: false, code: "empty", message: "Choose a username." };
  if (display.length < USERNAME_MIN || display.length > USERNAME_MAX) return { ok: false, code: "length", message: `Use ${USERNAME_MIN} to ${USERNAME_MAX} characters.` };
