};
const GROUPS = ["Operate", "People", "Money", "Product", "Community", "Launch"];

export default async function CyrusAdminTools() {
  await requireCyrusAdmin("tools");
  const me = await realUser();
  const tabs = me ? visibleCyrusTabs(me.role) : [];
  return (
    <div className="space-y-6">
      <p className="text-sm text-slate-400">Every Cyrus admin tool you may open with your role. Public Cyrus pages stay hidden until the launch switches are on (see Launch check and Mods launch).</p>
      {GROUPS.map((g) => {
        const items = tabs.filter((t) => ABOUT[t.id].group === g);
        if (!items.length) return null;
        return (
          <Section key={g} title={g}>
            <ul className="grid gap-3 sm:grid-cols-2">
              {items.map((t) => (
                <li key={t.id} className="rounded-lg border border-white/10 bg-white/[0.03] p-4">
                  <Link href={t.href} className="font-semibold text-slate-100 hover:underline">{t.label}</Link>
                  <p className="mt-1 text-sm text-slate-400">{ABOUT[t.id].what}</p>
                </li>
              ))}
            </ul>
          </Section>
        );
      })}
    </div>
  );
}

