/** Replace the marker block in a page. A page without markers is returned unchanged. */
export function applyFeatured(html, section) {
  const a = html.indexOf(START);
  const b = html.indexOf(END);
  if (a < 0 || b < a) return html;
  return html.slice(0, a + START.length) + (section ? `\n${section}\n` : "\n") + html.slice(b);
}

async function readCards(src) {
  const raw = /^https:\/\//.test(src) ? await (await fetch(src, { signal: AbortSignal.timeout(10_000) })).text() : readFileSync(src, "utf8");
  const j = JSON.parse(raw);
  return Array.isArray(j) ? j : j.cards;
}

async function main() {
  const arg = (n) => { const i = process.argv.indexOf(`--${n}`); return i > 0 ? process.argv[i + 1] : undefined; };
  const inFile = arg("in"); const out = arg("out") || inFile; const json = arg("json");
  if (!inFile || !json) { console.error("usage: featured.mjs --in index.html --json <file|url> [--out file] [--origin url]"); process.exit(2); }
  let cards = [];
  try { cards = await readCards(json); } catch (e) { console.error(`featured: source unreadable (${e.message}); section left out`); }
  const section = renderFeaturedSection(cards, { origin: arg("origin") || "" });
  writeFileSync(out, applyFeatured(readFileSync(inFile, "utf8"), section));
  console.log(`featured: ${section ? "section written" : "no featured mods, section left out"}`);
}

