      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={CYRUS_BRAND.wordmark.light} alt="" aria-hidden className="is-light" width={w} height={height} draggable={false} />
    </span>
  );
}

/** The token coin: the Y on a coin, standing still. */
export function TokenCoin({ size = 16, className = "" }: { size?: number; className?: string }) {
  return <CyrusToken size={size} mode="rest" className={className} />;
}

/** The same coin turning: tokens at work. Still under reduced motion. */
export function CoinSpin({ size = 20, className = "", label }: { size?: number; className?: string; label?: string }) {
  return <CyrusToken size={size} mode="spin" className={className} label={label} />;
}

