//   cyrusRobots()          the Cyrus-host robots.txt (bot policy = lib/seo-robots-policy.ts, the owner's Nxeon policy)
//   sitemap builders       urlset / sitemapindex XML with escaping, absolute https URLs, 50k sharding scaffold
//   cyrusXRobotsTag()      X-Robots-Tag value for non-public paths on the Cyrus host (middleware applies it)
//   gscVerification()      Google Search Console token (CYRUS_GSC_VERIFICATION): meta tag OR google<token>.html file
//   cyrusPageMetadata()    canonical + robots + verification for app-rendered pages on the Cyrus host
import type { Metadata, MetadataRoute } from "next";
import { robotsRules } from "../seo-robots-policy";

export const CYRUS_APEX_ORIGIN = "https://cyrus.my";
/** Sitemaps protocol limit is 50,000 URLs / 50 MB per file; stay below it. */
export const SITEMAP_MAX_URLS = 50_000;

const trimSlash = (s: string) => s.replace(/\/+$/, "");
/** The canonical Cyrus origin: https only (a configured http origin is upgraded), no trailing slash. */
export function cyrusSiteOrigin(env: Record<string, string | undefined> = process.env): string {
  const first = (env.CYRUS_HOSTS ?? "cyrus.my").split(",")[0]?.trim().toLowerCase().replace(/^www\./, "") || "cyrus.my";
  const raw = trimSlash(env.CYRUS_ORIGIN || `https://${first}`);
  return raw.replace(/^http:\/\//i, "https://");
}

// ---------------------------------------------------------------------------
// robots.txt
// ---------------------------------------------------------------------------
/**
 * Paths that are the signed-in application or machine endpoints. Everything else (landing, legal, help, plans and any
 * future public mod / library / spotlight path) stays allowed. `*` and `$` are honoured by Google, Bing and Apple.
 * `/sign-in` and `/sign-up` themselves stay crawlable (so the page's noindex is SEEN); only their parameterised
 * variants (?prompt=, ?next=) are disallowed. `/assets$` is the app's customer asset page; the landing's own files live
 * under /assets/ and MUST stay crawlable (CSS / images for rendering).
 */
export const CYRUS_DISALLOW = [
  "/new$", "/new/", "/new?*",
  "/home", "/dashboard", "/account", "/wallet", "/servers", "/projects", "/studio",
  "/assets$", "/assets?*",
  "/api/", "/auth/", "/admin", "/staff", "/packs/",
  "/sign-in?*", "/sign-up?*", "/login", "/register",
];

export function cyrusRobots(env: Record<string, string | undefined> = process.env): MetadataRoute.Robots {
  return {
    rules: robotsRules(CYRUS_DISALLOW, env),
    sitemap: `${cyrusSiteOrigin(env)}/sitemap.xml`,
  };
}

// ---------------------------------------------------------------------------
// X-Robots-Tag for non-public pages
// ---------------------------------------------------------------------------
const PRIVATE_PREFIXES = ["/sign-in", "/sign-up", "/auth", "/studio", "/home", "/dashboard", "/account", "/wallet", "/servers", "/projects", "/new", "/api", "/admin", "/staff", "/login", "/register", "/sso", "/cyrus-host"];
const under = (p: string, prefix: string) => p === prefix || p.startsWith(prefix + "/");

/** noindex value for a path on the Cyrus host that must never be indexed, else null (legal, help, plans, landing). */
export function cyrusXRobotsTag(pathname: string): string | null {
  if (pathname === "/assets") return "noindex, nofollow"; // the app page; /assets/<file> is landing static
  if (PRIVATE_PREFIXES.some((p) => under(pathname, p))) return "noindex, nofollow";
  return null;
}

// ---------------------------------------------------------------------------
// sitemap
// ---------------------------------------------------------------------------
export type SitemapUrl = { path: string; lastmod?: Date | string | null };
const XML_ESC: Record<string, string> = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&apos;" };
export const escapeXml = (s: string) => s.replace(/[&<>"']/g, (c) => XML_ESC[c]);

/** W3C date (YYYY-MM-DD) for a Date or an ISO-ish string; null when it is not a real date. */
export function lastmodDate(v: Date | string | null | undefined): string | null {
  if (!v) return null;
  const d = v instanceof Date ? v : new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}
/** "September 27, 2026" (the legal DOC.updated format) -> Date (UTC midnight), or null. */
export function parseLegalDate(s: string): Date | null {
  const d = new Date(`${s} 00:00:00 UTC`);
  return Number.isNaN(d.getTime()) ? null : d;
}

/** Absolute https URL on the Cyrus origin; the root keeps its slash, every other path has none ("/legal/terms"). */
export function absUrl(origin: string, path: string): string {
  const o = trimSlash(origin);
  if (!path || path === "/") return `${o}/`;
  const p = path.startsWith("/") ? path : `/${path}`;
  return o + (p.length > 1 && !p.includes("?") ? p.replace(/\/+$/, "") : p);
}

/** De-duplicate by path (first wins), keep order. */
export function uniqueUrls(urls: SitemapUrl[]): SitemapUrl[] {
  const seen = new Set<string>();
  return urls.filter((u) => (seen.has(u.path) ? false : (seen.add(u.path), true)));
}
export function shardUrls<T>(urls: T[], max = SITEMAP_MAX_URLS): T[][] {
  if (urls.length === 0) return [[]];
  const out: T[][] = [];
  for (let i = 0; i < urls.length; i += max) out.push(urls.slice(i, i + max));
  return out;
}

export function urlsetXml(origin: string, urls: SitemapUrl[]): string {
  const rows = urls.map((u) => {
    const lm = lastmodDate(u.lastmod);
    return `  <url>\n    <loc>${escapeXml(absUrl(origin, u.path))}</loc>${lm ? `\n    <lastmod>${lm}</lastmod>` : ""}\n  </url>`;
  });
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${rows.join("\n")}\n</urlset>\n`;
}

/** Child sitemap locations are `<origin>/sitemap.xml?page=N` (served by the same route; N is 1-based). */
export function sitemapIndexXml(origin: string, shards: SitemapUrl[][]): string {
  const rows = shards.map((s, i) => {
    const newest = s.map((u) => lastmodDate(u.lastmod)).filter((x): x is string => !!x).sort().pop();
    return `  <sitemap>\n    <loc>${escapeXml(`${trimSlash(origin)}/sitemap.xml?page=${i + 1}`)}</loc>${newest ? `\n    <lastmod>${newest}</lastmod>` : ""}\n  </sitemap>`;
  });
  return `<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${rows.join("\n")}\n</sitemapindex>\n`;
}

/**
 * The sitemap document for `page` (undefined = the main file): the urlset itself while everything fits in one file,
 * otherwise the index; ?page=N is shard N. Returns null for a page that does not exist (the route answers 404).
 */
export function sitemapDocument(origin: string, all: SitemapUrl[], page?: number | null, max = SITEMAP_MAX_URLS): string | null {
  const urls = uniqueUrls(all);
  const shards = shardUrls(urls, max);
  if (page == null) return shards.length <= 1 ? urlsetXml(origin, urls) : sitemapIndexXml(origin, shards);
  if (!Number.isInteger(page) || page < 1 || page > shards.length || shards.length <= 1) return null;
  return urlsetXml(origin, shards[page - 1]);
}

export type CyrusSitemapInput = {
  /** Real last-change date of the landing (release.json builtAt); omitted when unknown. */
  homeLastmod?: Date | null;
  /** [path, DOC.updated] for each legal page. */
  legal: Array<{ path: string; updated: string }>;
  /** cyrus_mods_public_enabled (lib/cyrus-mods/gate.ts) AND CYRUS_SITEMAP_MOD_PAGES=1 (cyrus.my really serves them). */
  modPagesOn: boolean;
  modPages?: Array<{ slug: string; updatedAt: Date }>;
  /** Placeholders for surfaces that do not exist yet; they emit nothing until their own gates are wired. */
  libraryPages?: SitemapUrl[];
  spotlightPages?: SitemapUrl[];
};

