  it("empty or invalid input renders nothing and leaves the markers empty", () => {
    assert.equal(renderFeaturedSection([]), "");
    assert.equal(renderFeaturedSection([{ slug: "../x", title: "t" }, { slug: "ok", title: "" }]), "");
    const page = `a\n${START}\nOLD\n${END}\nb`;
    assert.equal(applyFeatured(page, ""), `a\n${START}\n${END}\nb`);
    assert.ok(applyFeatured(page, "<section/>").includes("<section/>"));
    assert.ok(!applyFeatured(page, "<section/>").includes("OLD"));
    assert.equal(applyFeatured("no markers", "<s/>"), "no markers");
