process.env.DATABASE_URL ||= "postgresql://nobody:nothing@127.0.0.1:1/none?connect_timeout=2";
const dir = path.resolve(__dirname, "..", "node_modules", "server-only"), idx = path.join(dir, "index.js"), SHIM = "module.exports = {};\n";
if (!existsSync(idx) || readFileSync(idx, "utf8") !== SHIM) {
  mkdirSync(dir, { recursive: true });
  writeFileSync(path.join(dir, "package.json"), '{"name":"server-only","version":"0.0.0","main":"index.js","browser":"index.js"}\n');
  writeFileSync(idx, SHIM);
}
