// Public content surface of cyrus.my (games, mods, host, blog): the path map. PURE and Edge-safe (middleware imports it
// through lib/cyrus/bridge/routing.ts; tests pin it). Same pattern as the help center (lib/cyrus/help/paths.ts): on the
// Cyrus host the public path is /games, /mods, /host, /blog; the pages themselves live in the internal tree
// /cyrus-web, which is also reachable on every other host (noindex there, canonical = cyrus.my) so the same pages can
// be reused on nxeon.cloud without a second copy.
//
//   /games                 /cyrus-web/games
//   /games/<game>          /cyrus-web/games/<game>
//   /mods                  /cyrus-web/mods
//   /mods/<slug>           /cyrus-web/mods/<slug>
//   /host                  /cyrus-web/host
//   /host/<a>              /cyrus-web/host/<a>            game OR location
//   /host/<game>/<place>   /cyrus-web/host/<game>/<place>
//   /blog                  /cyrus-web/blog
//   /blog/<slug>           /cyrus-web/blog/<slug>
//   /blog/rss.xml          /cyrus-web/blog/rss.xml        (route handler)
export const WEB_BASE_INTERNAL = "/cyrus-web";

const SLUG = /^[a-z0-9][a-z0-9-]{0,80}$/;
export const isWebSlug = (s: unknown): s is string => typeof s === "string" && SLUG.test(s);

/** The four public roots (nginx and the middleware allow-list are derived from this list). */
export const WEB_ROOTS = ["games", "mods", "host", "blog"] as const;
export type WebRoot = (typeof WEB_ROOTS)[number];

/** Public cyrus.my path -> internal path (null = not a content path). Query strings are the caller's. */
export function webPath(p: string): string | null {
  const parts = p.split("/").filter((x, i) => !(i === 0 && x === ""));
  if (!parts.length) return null;
  const root = parts[0] as WebRoot;
  if (!(WEB_ROOTS as readonly string[]).includes(root)) return null;
  if (p.endsWith("/") && p.length > 1) return null; // no trailing-slash duplicates: the app 404s them
  const rest = parts.slice(1);
  if (root === "blog" && rest.length === 1 && rest[0] === "rss.xml") return `${WEB_BASE_INTERNAL}/blog/rss.xml`;
  const max = root === "host" ? 2 : root === "blog" || root === "games" || root === "mods" ? 1 : 0;
  if (rest.length > max) return null;
  if (!rest.every(isWebSlug)) return null;
  return [WEB_BASE_INTERNAL, root, ...rest].join("/");
}

/** Where a link should point: the public path on the Cyrus host, the internal one elsewhere. */
export const webHref = (onCyrus: boolean, path: string): string => (onCyrus ? path : `${WEB_BASE_INTERNAL}${path}`);

