// Cyrus SPOTLIGHT (2026-10-15): the honest way to show "the best mods of the week".
//
// What it is NOT: a ranking by invented views or ratings. Nothing here fabricates, inflates or backfills a number. The
// spotlight is EDITORIAL: staff choose mods in the admin (Setting `cyrus_spotlight_picks`), each pick carrying a reason
// line, an order and optional start/end dates. Pages label them for what they are: "Staff pick" and "Mod of the week".
// REAL signals (views, installs, ratings) are counted separately (lib/cyrus-site/views.ts, lib/cyrus-mods/social.ts) and
// may blend in later, but only past a minimum sample (SIGNAL_MIN) and only as a separate, honestly-named section
// ("Popular right now") behind its own switch. Below the threshold a counter is shown as "New", never as a number.
//
// PURE: no DB, no Nxeon imports. The server half is ./spotlight.server.ts. Tests: test/cyrus-content.test.ts.

export const SPOTLIGHT_KEY = "cyrus_spotlight_picks";
export const SPOTLIGHT_POPULAR_KEY = "cyrus_spotlight_popular_enabled";
export const SPOTLIGHT_MAX_PICKS = 60;
export const SPOTLIGHT_REASON_MAX = 140;
/** A "Mod of the week" with no end date runs this long. */
export const WEEK_DAYS = 7;
export const THIS_WEEK_MAX = 3;
export const STAFF_PICKS_MAX = 12;
export const POPULAR_MAX = 6;
/** The "Popular right now" section needs at least this many mods past a threshold, else it is not shown at all. */
export const POPULAR_MIN_MODS = 3;

export type SpotlightKind = "week" | "staff";

export type SpotlightPick = {
  /** CyrusModPage.id */
  id: string;
  kind: SpotlightKind;
  /** One line, why staff picked it. Shown under the card. Required. */
  reason: string;
  /** Lower = earlier. */
  order: number;
  /** ISO date-time. null = from the start. */
  startsAt: string | null;
  /** ISO date-time. null = no end (staff picks only; a week pick is always given one). */
  endsAt: string | null;
  addedAt: string;
};

const DAY = 86_400_000;
const ID = /^[A-Za-z0-9_-]{1,64}$/;
const iso = (v: unknown): string | null => {
  if (typeof v !== "string" || !v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};

/** Clean one-line reason text: trims, collapses whitespace, strips control characters and angle brackets, caps length. */
export function cleanReason(raw: unknown): string {
  const s = typeof raw === "string" ? raw : "";
  return s.replace(/[\u0000-\u001f\u007f<>]/g, " ").replace(/\s+/g, " ").trim().slice(0, SPOTLIGHT_REASON_MAX);
}

/** Defensive parse of the stored JSON. Bad rows are dropped, never repaired into something the admin did not write. */
export function parseSpotlight(raw: string | null | undefined): SpotlightPick[] {
  if (!raw) return [];
  let v: unknown;
  try { v = JSON.parse(raw); } catch { return []; }
  if (!Array.isArray(v)) return [];
  const out: SpotlightPick[] = [];
  const seen = new Set<string>();
  for (const x of v) {
    if (!x || typeof x !== "object") continue;
    const r = x as Record<string, unknown>;
    const id = typeof r.id === "string" ? r.id : "";
    const kind = r.kind === "week" || r.kind === "staff" ? r.kind : null;
    const reason = cleanReason(r.reason);
    if (!ID.test(id) || !kind || !reason) continue;
    const key = `${kind}:${id}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      id, kind, reason,
      order: Number.isFinite(Number(r.order)) ? Math.max(0, Math.min(9999, Math.round(Number(r.order)))) : 0,
      startsAt: iso(r.startsAt), endsAt: iso(r.endsAt),
      addedAt: iso(r.addedAt) ?? new Date(0).toISOString(),
    });
    if (out.length >= SPOTLIGHT_MAX_PICKS) break;
  }
