/** Validate one admin submission into a pick. A week pick always gets an end (start + 7 days unless given). */
export function validatePick(i: PickInput, now: Date): PickCheck {
  const id = typeof i.id === "string" ? i.id : "";
  if (!ID.test(id)) return { ok: false, error: "Pick a mod." };
  if (i.kind !== "week" && i.kind !== "staff") return { ok: false, error: "Pick Mod of the week or Staff pick." };
  const reason = cleanReason(i.reason);
  if (reason.length < 3) return { ok: false, error: "Write the one-line reason (it is shown on the page)." };
  const startsAt = iso(i.startsAt);
  let endsAt = iso(i.endsAt);
  if (i.kind === "week") {
    const s = startsAt ?? now.toISOString();
    if (!endsAt) endsAt = new Date(new Date(s).getTime() + WEEK_DAYS * DAY).toISOString();
    if (new Date(endsAt).getTime() <= new Date(s).getTime()) return { ok: false, error: "The end must be after the start." };
    return { ok: true, pick: { id, kind: "week", reason, order: clampOrder(i.order), startsAt: s, endsAt, addedAt: now.toISOString() } };
  }
  if (startsAt && endsAt && new Date(endsAt).getTime() <= new Date(startsAt).getTime()) return { ok: false, error: "The end must be after the start." };
