export function upsertPick(list: SpotlightPick[], pick: SpotlightPick): { ok: true; list: SpotlightPick[] } | { ok: false; error: string } {
  const rest = list.filter((p) => !(p.id === pick.id && p.kind === pick.kind));
  if (rest.length >= SPOTLIGHT_MAX_PICKS) return { ok: false, error: `At most ${SPOTLIGHT_MAX_PICKS} picks are kept. Remove an old one first.` };
  return { ok: true, list: [...rest, pick] };
}
export const removePick = (list: SpotlightPick[], id: string, kind: SpotlightKind) => list.filter((p) => !(p.id === id && p.kind === kind));

/** Is this pick running at `now`? start <= now < end; a missing bound is open. */
export function pickActive(p: Pick<SpotlightPick, "startsAt" | "endsAt">, now: Date): boolean {
  const t = now.getTime();
  if (p.startsAt && new Date(p.startsAt).getTime() > t) return false;
  if (p.endsAt && new Date(p.endsAt).getTime() <= t) return false;
  return true;
}
export type PickState = "live" | "scheduled" | "ended";
export function pickState(p: Pick<SpotlightPick, "startsAt" | "endsAt">, now: Date): PickState {
  if (p.startsAt && new Date(p.startsAt).getTime() > now.getTime()) return "scheduled";
  if (p.endsAt && new Date(p.endsAt).getTime() <= now.getTime()) return "ended";
  return "live";
}

const byOrder = (a: SpotlightPick, b: SpotlightPick) => a.order - b.order || (b.startsAt ?? "").localeCompare(a.startsAt ?? "") || a.addedAt.localeCompare(b.addedAt);

export type SpotlightSelection = {
  /** The one headline mod, or null. */
  modOfWeek: SpotlightPick | null;
  /** "This week": the live week picks, headline first (max THIS_WEEK_MAX). */
  thisWeek: SpotlightPick[];
  /** "Staff picks": live staff picks, plus the owner's older featured list (reason null), max STAFF_PICKS_MAX. */
  staffPicks: Array<SpotlightPick | (Omit<SpotlightPick, "reason"> & { reason: null })>;
};

/**
 * What is live right now. The older single list (Setting cyrus_featured_pages, lib/cyrus-mods/featured.ts) keeps
 * working: its ids appear as staff picks without a reason, after the dated ones.
 */
export function selectSpotlight(picks: SpotlightPick[], now: Date, legacyFeaturedIds: string[] = []): SpotlightSelection {
  const live = picks.filter((p) => pickActive(p, now));
  const week = live.filter((p) => p.kind === "week").sort(byOrder).slice(0, THIS_WEEK_MAX);
  const staff: SpotlightSelection["staffPicks"] = live.filter((p) => p.kind === "staff").sort(byOrder);
  const have = new Set([...staff.map((p) => p.id), ...week.map((p) => p.id)]);
  legacyFeaturedIds.forEach((id, i) => {
    if (have.has(id) || !ID.test(id)) return;
    have.add(id);
    staff.push({ id, kind: "staff", reason: null, order: 10_000 + i, startsAt: null, endsAt: null, addedAt: new Date(0).toISOString() });
  });
