// ---------------------------------------------------------------------------

/** Minimum real sample before a signal counts at all. Below it a counter reads "New". */
export const SIGNAL_MIN = { views7d: 25, installers: 3, ratings: 5 } as const;

export type Signals = {
  /** Real page views in the last 7 UTC days (bots and the creator excluded). null = no counter available. */
  views7d: number | null;
  /** Distinct OTHER accounts that have it on a server. */
  installers: number;
  /** Ratings from other accounts. */
  ratings: { count: number; average: number | null };
};

export const meetsSample = (s: Signals) =>
  (s.views7d ?? 0) >= SIGNAL_MIN.views7d || s.installers >= SIGNAL_MIN.installers || s.ratings.count >= SIGNAL_MIN.ratings;

/**
 * A transparent score for "Popular right now". null when nothing passes its minimum sample (so a mod with 2 ratings
 * and 4 views can never outrank anything). Components only count once their own threshold is met:
 *   views:      log10(1 + views7d)                              (diminishing returns)
 *   installers: 2 per distinct other account
 *   rating:     (average - 3) * min(count, 20) / 5               (negative below 3 stars; capped sample weight)
 */
export function signalScore(s: Signals): number | null {
  if (!meetsSample(s)) return null;
  let score = 0;
  if ((s.views7d ?? 0) >= SIGNAL_MIN.views7d) score += Math.log10(1 + (s.views7d ?? 0));
  if (s.installers >= SIGNAL_MIN.installers) score += 2 * s.installers;
  if (s.ratings.count >= SIGNAL_MIN.ratings && s.ratings.average != null) score += ((s.ratings.average - 3) * Math.min(s.ratings.count, 20)) / 5;
  return Math.round(score * 100) / 100;
}

/** The "Popular right now" list: scored mods only, best first; empty unless at least POPULAR_MIN_MODS qualify. */
export function popularList<T extends { id: string; signals: Signals }>(items: T[]): T[] {
  const scored = items.map((it) => ({ it, s: signalScore(it.signals) })).filter((x): x is { it: T; s: number } => x.s != null);
  if (scored.length < POPULAR_MIN_MODS) return [];
  return scored.sort((a, b) => b.s - a.s || a.it.id.localeCompare(b.it.id)).slice(0, POPULAR_MAX).map((x) => x.it);
}

// ---------------------------------------------------------------------------
// Display strings (used by pages, the JSON API and the landing generator: one wording)
// ---------------------------------------------------------------------------

/** "New" until a rating is real; never a number from nothing. */
export function ratingText(r: { count: number; average: number | null } | null | undefined): string {
  if (!r || r.count < 1 || r.average == null) return "New";
  return `${r.average.toFixed(1)} / 5 (${r.count})`;
}
/** Views: only once at least SIGNAL_MIN.views7d... no: a total is shown as soon as it is real and >= 1; below 1 it is "New". */
export function countText(n: number | null | undefined, one: string, many: string): string {
  if (n == null || n < 1) return "New";
  return `${n.toLocaleString("en-US")} ${n === 1 ? one : many}`;
}
export const BADGE = { week: "Mod of the week", staff: "Staff pick" } as const;

