// Real page-view counters for PUBLIC Cyrus mod pages (2026-10-15). SERVER ONLY.
//
// Honesty contract: a count here is a count of real server renders of the public mod page by a non-bot, not the creator,
// one increment per render (a refresh counts: this is "page views", labelled as such, never "visitors"). It starts at 0
// for every mod. Nothing seeds, boosts or estimates it. If the table is missing (schema not applied) or a read fails,
// callers get null and the page says "New". Writes never throw into the page render.
import { cyrusDb } from "../cyrus/db";

const DAY = 86_400_000;
export const utcDay = (d: Date) => d.toISOString().slice(0, 10);

/** Crawlers, link unfurlers, uptime probes and headless fetchers are not viewers. Conservative: unknown UA counts as a bot. */
const BOT = /bot|crawl|spider|slurp|bingpreview|facebookexternalhit|embedly|quora link|whatsapp|telegram|discord|slack|preview|fetch|curl|wget|python|httpx|axios|node-|go-http|java\/|okhttp|monitor|uptime|pingdom|lighthouse|headless|phantom|puppeteer|playwright|selenium|gptbot|claude|perplexity|ahrefs|semrush|mj12|dotbot|petalbot|yandex|baidu|duckduck|applebot|cloudflare/i;
export function isLikelyHuman(userAgent: string | null | undefined): boolean {
  const ua = (userAgent ?? "").trim();
  if (ua.length < 20) return false;
  return !BOT.test(ua);
}

/** The last `days` UTC day keys ending today (inclusive), oldest first. */
export function lastDays(now: Date, days: number): string[] {
  return Array.from({ length: days }, (_, i) => utcDay(new Date(now.getTime() - (days - 1 - i) * DAY)));
}

/** Record one view. Never throws. Returns whether a row was written. */
export async function recordModView(args: { pageId: string; userAgent: string | null; viewerIsCreator: boolean; now?: Date }): Promise<boolean> {
  if (args.viewerIsCreator || !isLikelyHuman(args.userAgent)) return false;
