import { OFFICIAL_KEY, isOfficialAuthor, parseOfficialIds } from "./official";
import { viewCounts, type ViewCounts } from "./views";
import { SPOTLIGHT_KEY, parseSpotlight, selectSpotlight, type SpotlightPick } from "./spotlight";
import { readFeaturedIds } from "../cyrus-mods/featured";

export const officialUserIds = async () => parseOfficialIds(await getSetting(OFFICIAL_KEY, "").catch(() => ""));

export type SiteCategory = { id: CyrusCategoryId; label: string; blurb: string };
const catOf = (id: string | null | undefined): SiteCategory | null => {
  const c = CYRUS_CATEGORIES.find((x) => x.id === id);
  return c ? { id: c.id, label: c.label, blurb: c.blurb } : null;
};
export const allCategories = (): SiteCategory[] => CYRUS_CATEGORIES.map((c) => ({ id: c.id, label: c.label, blurb: c.blurb }));
export const isCategoryId = (v: unknown): v is CyrusCategoryId => typeof v === "string" && (CYRUS_CATEGORY_IDS as readonly string[]).includes(v);

export type SiteModCard = {
  id: string;
  slug: string;
  title: string;
  tagline: string | null;
  /** The public author TAG (never the account name). */
  author: string;
  official: boolean;
  game: "Minecraft";
  mcVersions: string[];
  version: string | null;
  category: SiteCategory | null;
  tags: string[];
  iconUrl: string | null;
  /** A REAL image the creator/staff uploaded (banner, else first photo); null = the page draws an illustration instead. */
  coverUrl: string | null;
  coverAlt: string;
  updatedAt: string;
  publishedAt: string | null;
  flight: "passed" | "failed" | null;
  /** Real counters. null/0 = shown as "New". */
  views: number | null;
  views7d: number | null;
  installers: number;
  servers: number;
  stars: number;
  rating: { count: number; average: number | null };
  /** "boot-tested on Paper 1.21.11" style label from the Test Flight, only when it ran. */
  flightLabel: string | null;
};

type PageRow = Awaited<ReturnType<typeof cyrusDb.cyrusModPage.findMany>>[number];

function categoryFor(row: PageRow, doc: CyrusModDoc, lv: ListingView): SiteCategory | null {
  if (isCategoryId(lv.category)) return catOf(lv.category);
  const r = autoSort({ title: row.title, summary: [doc.tagline, doc.summary].filter(Boolean).join(" "), commands: doc.commands, permissions: doc.permissions, config: doc.config });
  return r.confident ? catOf(r.primary) : null;
}

async function toCards(rows: PageRow[], now = new Date()): Promise<SiteModCard[]> {
  if (!rows.length) return [];
  const [stats, lm, tags, official, views] = await Promise.all([
    statsFor(rows).catch(() => new Map<string, PageStats>()),
    listingsFor(rows.map((r) => r.id)).catch(() => ({ listings: new Map(), media: new Map() })),
    authorTags(rows.map((r) => r.userId)).catch(() => new Map<string, string>()),
    officialUserIds(),
    viewCounts(rows.map((r) => r.id), now),
  ]);
  return rows.flatMap((r): SiteModCard[] => {
    const doc = readModDoc(r.doc);
    if (!doc) return [];
    const lv = toListingView(lm.listings.get(r.id) ?? null, lm.media.get(r.id) ?? [], false);
    const st = stats.get(r.id);
    const vc: ViewCounts | undefined = views?.get(r.id);
    const cover = lv.banner ?? lv.photos[0] ?? null;
    return [{
      id: r.id, slug: r.slug, title: r.title,
      tagline: lv.tagline ?? r.tagline ?? doc.tagline ?? null,
      author: tags.get(r.userId) ?? "Cyrus creator",
      official: isOfficialAuthor(r.userId, official),
      game: "Minecraft",
      mcVersions: doc.compat.mcVersions, version: r.latestVersion,
      category: categoryFor(r, doc, lv), tags: lv.tags.slice(0, 6),
      iconUrl: lv.icon?.url ?? null,
      coverUrl: cover?.url ?? null,
      coverAlt: cover?.caption?.trim() || `${r.title}, a Minecraft plugin made with Cyrus`,
      updatedAt: r.updatedAt.toISOString(), publishedAt: r.publishedAt?.toISOString() ?? null,
      flight: flightFailedVerdict(doc.testFlight) ? "failed" : doc.testFlight?.verdict === "passed" ? "passed" : null,
      views: views === null ? null : vc?.total ?? 0, views7d: views === null ? null : vc?.last7d ?? 0,
      installers: st?.installers ?? 0, servers: st?.servers ?? 0, stars: st?.stars ?? 0,
      rating: st?.ratings ?? { count: 0, average: null },
      flightLabel: doc.testFlight?.verdict === "passed" ? doc.testFlight.label ?? null : null,
    }];
  });
}

const PUBLIC = { visibility: "PUBLIC", hiddenAt: null } as const;

/** Public pages, newest update first. A page whose current version FAILED its Test Flight is not listed. */
export async function loadSiteMods(opts: { q?: string; category?: string | null; take?: number; skip?: number } = {}): Promise<{ cards: SiteModCard[]; total: number }> {
  const q = (opts.q ?? "").trim().slice(0, 60);
  const where = q ? { ...PUBLIC, OR: [{ title: { contains: q, mode: "insensitive" as const } }, { tagline: { contains: q, mode: "insensitive" as const } }] } : PUBLIC;
  // A category filter is applied after the card build (category is derived), over a bounded window.
  const take = Math.min(opts.take ?? 48, 100);
  const rows = await cyrusDb.cyrusModPage.findMany({ where, orderBy: { updatedAt: "desc" }, take: opts.category ? 400 : take, skip: opts.category ? 0 : opts.skip ?? 0 }).catch(() => []);
  let cards = (await toCards(rows)).filter((c) => c.flight !== "failed");
  if (opts.category) cards = cards.filter((c) => c.category?.id === opts.category);
  const total = cards.length;
  return { cards: opts.category ? cards.slice(opts.skip ?? 0, (opts.skip ?? 0) + take) : cards, total };
}

export async function loadSiteModsByIds(ids: string[]): Promise<SiteModCard[]> {
  if (!ids.length) return [];
  const rows = await cyrusDb.cyrusModPage.findMany({ where: { ...PUBLIC, id: { in: ids } } }).catch(() => []);
  const by = new Map((await toCards(rows)).filter((c) => c.flight !== "failed").map((c) => [c.id, c]));
  return ids.flatMap((id) => (by.has(id) ? [by.get(id)!] : []));
}

/** How many public mods fall in each category (derived; only categories with at least one mod appear). */
export async function categoryCounts(): Promise<Array<SiteCategory & { count: number }>> {
  const { cards } = await loadSiteMods({ take: 100 });
  const n = new Map<string, number>();
  for (const c of cards) if (c.category) n.set(c.category.id, (n.get(c.category.id) ?? 0) + 1);
  return allCategories().filter((c) => n.has(c.id)).map((c) => ({ ...c, count: n.get(c.id)! }));
}

export type SiteModDetail = SiteModCard & {
  summary: string | null;
  howToUse: string[];
  limitations: string[];
  commands: { usage: string; description: string; permission: string | null }[];
  versions: { version: string | null; mcVersion: string; at: string; notes: string; safety: "pass" | "warn" | "block" | null; current: boolean }[];
  photos: { url: string; caption: string | null; width: number | null; height: number | null }[];
  descriptionHtml: string;
  links: { label: string; url: string }[];
  license: string;
  assetLines: string[];
  flightLines: string[];
  tested: { earned: boolean; passed: number; total: number };
  /** The page is rich enough to be indexed (see modIndexable). */
  indexable: boolean;
};

/** Indexing quality bar (docs/cyrus/20-content.md): enough real text to be useful and a Test Flight that did not fail. */
export function modIndexable(d: { summary: string | null; commands: number; features: number; flight: "passed" | "failed" | null; hidden?: boolean }): boolean {
  if (d.hidden || d.flight === "failed") return false;
  return (d.summary?.trim().length ?? 0) >= 120 && d.commands + d.features >= 1;
}

export async function loadSiteMod(slug: string): Promise<SiteModDetail | null> {
  if (!/^[a-z0-9-]{3,60}$/.test(slug)) return null;
  const row = await cyrusDb.cyrusModPage.findUnique({ where: { slug } }).catch(() => null);
  if (!row || row.visibility !== "PUBLIC" || row.hiddenAt) return null;
  const doc = readModDoc(row.doc);
  if (!doc) return null;
  const [card] = await toCards([row]);
  if (!card) return null;
  const { listings, media } = await listingsFor([row.id]).catch(() => ({ listings: new Map(), media: new Map() }));
  const lv = toListingView(listings.get(row.id) ?? null, media.get(row.id) ?? [], false);
  const stats = (await statsFor([row]).catch(() => new Map<string, PageStats>())).get(row.id);
  const tested = stats ? testedFor(row, doc, stats) : null;
  const current = doc.versions.find((v) => v.buildId === doc.currentBuildId) ?? doc.versions[0];
  return {
    ...card,
    summary: doc.summary,
    howToUse: doc.howToUse.slice(0, 8),
    limitations: doc.limitations.slice(0, 8),
    commands: doc.commands.slice(0, 24).map((c) => ({ usage: c.usage, description: c.description ?? "", permission: c.permission ?? null })),
    versions: doc.versions.slice(0, 12).map((v) => ({ version: v.version, mcVersion: v.mcVersion, at: v.at, notes: v.notes, safety: v.safety, current: v.buildId === current?.buildId })),
    photos: lv.photos.slice(0, 8).map((p) => ({ url: p.url, caption: p.caption, width: p.width, height: p.height })),
    descriptionHtml: lv.descriptionHtml,
    links: lv.links,
    license: row.license,
    assetLines: doc.assets?.lines ?? [],
    flightLines: doc.testFlight?.verdict === "passed" ? doc.testFlight.lines.slice(0, 6) : [],
    tested: { earned: !!tested?.earned, passed: tested?.passed ?? 0, total: tested?.checks.length ?? 0 },
    indexable: modIndexable({ summary: doc.summary, commands: doc.commands.length, features: (doc.config?.length ?? 0) + (doc.assets ? 1 : 0), flight: card.flight }),
  };
}

export type SpotlightCard = SiteModCard & { badge: "Mod of the week" | "Staff pick"; reason: string | null; until: string | null };
export type SpotlightView = { modOfWeek: SpotlightCard | null; thisWeek: SpotlightCard[]; staffPicks: SpotlightCard[] };

/** The live spotlight: only PUBLIC, not-taken-down, flight-not-failed mods; a pick that no longer qualifies silently drops. */
export async function loadSpotlight(now = new Date()): Promise<SpotlightView> {
  const [raw, legacy] = await Promise.all([getSetting(SPOTLIGHT_KEY, "").catch(() => ""), readFeaturedIds().catch(() => [] as string[])]);
  const sel = selectSpotlight(parseSpotlight(raw), now, legacy);
  const ids = [...new Set([...sel.thisWeek.map((p) => p.id), ...sel.staffPicks.map((p) => p.id)])];
  const cards = new Map((await loadSiteModsByIds(ids)).map((c) => [c.id, c]));
  const mk = (p: Pick<SpotlightPick, "id" | "kind" | "endsAt"> & { reason: string | null }): SpotlightCard[] => {
    const c = cards.get(p.id);
    return c ? [{ ...c, badge: p.kind === "week" ? "Mod of the week" : "Staff pick", reason: p.reason, until: p.endsAt }] : [];
  };
  const thisWeek = sel.thisWeek.flatMap(mk);
  return { modOfWeek: thisWeek[0] ?? null, thisWeek, staffPicks: sel.staffPicks.flatMap(mk) };
}
