// The "Made by the Cyrus team" author tag (2026-10-15). PURE.
//
// Seed content on the public pages is REAL mods that Cyrus actually built (the owner batch and the dungeon builds), shown
// under one clearly-labelled official author, never under invented creators. Which accounts are official is a Setting
// (`cyrus_official_user_ids`, a JSON array of user ids) so it is an audited admin decision, not a code constant. Creators
// who are not in that list never get the badge; a username cannot claim it (the words cyrus/official/staff are reserved
// in lib/cyrus-mods/username.ts).
export const OFFICIAL_KEY = "cyrus_official_user_ids";
export const OFFICIAL_LABEL = "Made by the Cyrus team";
export const OFFICIAL_BADGE = "Cyrus team";

export function parseOfficialIds(raw: string | null | undefined): string[] {
  if (!raw) return [];
  try {
    const v = JSON.parse(raw) as unknown;
    if (!Array.isArray(v)) return [];
    return [...new Set(v.filter((x): x is string => typeof x === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(x)))].slice(0, 20);
  } catch { return []; }
}
export const isOfficialAuthor = (userId: string, ids: readonly string[]) => ids.includes(userId);
