    if (!slug) continue;
    const cur = by.get(slug);
    if (cur) cur.regions.push(r);
    else by.set(slug, { slug, name, country: (countryOf(r) ?? "").toLowerCase(), regions: [r] });
  }
  return [...by.values()].sort((a, b) => a.name.localeCompare(b.name));
}

// ── routing a /host/... request onto the catalogue ──────────────────────────

export type HostRoute =
  | { kind: "hub" }
  | { kind: "game"; game: HostGame }
  | { kind: "location"; loc: HostLocation }
  | { kind: "combo"; game: HostGame; loc: HostLocation }
  | null;

export function resolveHost(cat: HostCatalog, a?: string | null, b?: string | null): HostRoute {
  if (!a) return { kind: "hub" };
  const game = cat.games.find((g) => g.slug === a);
  const loc = cat.locations.find((l) => l.slug === a);
  if (!b) return game ? { kind: "game", game } : loc ? { kind: "location", loc } : null;
  const loc2 = cat.locations.find((l) => l.slug === b);
  // /host/<game>/<location> only. A location first (/host/singapore/minecraft) is not a URL we publish.
  return game && loc2 ? { kind: "combo", game, loc: loc2 } : null;
}

export type TemplateName = "showcase" | "place" | "compact";
/** The three page layouts: a game's page, a location's page, a game-in-a-location page. */
export const templateFor = (r: NonNullable<HostRoute>): TemplateName | "hub" => (r.kind === "game" ? "showcase" : r.kind === "location" ? "place" : r.kind === "combo" ? "compact" : "hub");

// ── indexing policy (thin-page guard) ───────────────────────────────────────

export type IndexPolicyInput = {
  /** Setting cyrus_content_index_enabled: the owner's "let search engines in" switch. */
  indexingOn: boolean;
  /** Extra families the owner allows into the index (Setting cyrus_host_index_games, comma list). */
  allowFamilies: string[];
};

/**
 * Only pages with value that is specific to Cyrus are indexable: the game must be one Cyrus builds for (or one the owner
 * explicitly allowed). Every other combination still renders (real data, honest) but is noindex,follow and never in the
 * sitemap, so the matrix cannot become a doorway-page farm (the 2026-10 SEO audit flagged exactly that on nxeon.cloud).
 */
export function gameIndexable(g: HostGame, p: IndexPolicyInput): boolean {
  return p.indexingOn && g.plans.length > 0 && (g.cyrusLive || p.allowFamilies.includes(g.family));
}
export function routeIndexable(r: NonNullable<HostRoute>, cat: HostCatalog, p: IndexPolicyInput): boolean {
  if (!p.indexingOn) return false;
  if (r.kind === "hub") return cat.games.some((g) => gameIndexable(g, p)) && cat.locations.length > 0;
  if (r.kind === "game") return gameIndexable(r.game, p);
  if (r.kind === "location") return cat.games.some((g) => gameIndexable(g, p));
  return gameIndexable(r.game, p) && r.loc.regions.length > 0;
}

/** Every indexable path (sitemap). Capped so a large catalogue can never flood the index. */
export const HOST_INDEX_MAX = 2000;
export function hostIndexablePaths(cat: HostCatalog, p: IndexPolicyInput): string[] {
  if (!p.indexingOn) return [];
  const out: string[] = [];
  if (routeIndexable({ kind: "hub" }, cat, p)) out.push("/host");
  const games = cat.games.filter((g) => gameIndexable(g, p));
  for (const g of games) out.push(`/host/${g.slug}`);
  if (games.length) for (const l of cat.locations) out.push(`/host/${l.slug}`);
  for (const g of games) for (const l of cat.locations) out.push(`/host/${g.slug}/${l.slug}`);
  return out.slice(0, HOST_INDEX_MAX);
}

// ── the discount code block ─────────────────────────────────────────────────

export type CouponRow = {
  code: string;
  kind: string;
  value: number;
  scope: string;
  serviceKind: string;
  planSlug: string | null;
  maxTermMonths: number | null;
  firstTimeOnly: boolean;
  excludeActiveCustomers: boolean;
  maxRedemptions: number | null;
  timesRedeemed: number;
  expiresAt: Date | null;
  active: boolean;
  trialDays: number | null;
};
export type CouponFacts = { code: string; headline: string; fineprint: string[] };

/**
 * What the code does, from the row itself. null = do not show a discount block at all. Conservative on purpose: a coupon
 * locked to one plan, a trial coupon or a wallet-credit coupon is not described (the page cannot state it truthfully).
 */
export function couponFacts(row: CouponRow | null | undefined, now: Date): CouponFacts | null {
  if (!row || !row.active) return null;
  if (row.expiresAt && row.expiresAt.getTime() <= now.getTime()) return null;
  if (row.maxRedemptions != null && row.timesRedeemed >= row.maxRedemptions) return null;
  if (row.serviceKind !== "ANY" && row.serviceKind !== "GAME") return null;
  if (row.scope !== "ANY" && row.scope !== "ORDER") return null;
  if (row.planSlug || (row.trialDays ?? 0) > 0) return null;
  const months = row.maxTermMonths && row.maxTermMonths > 0 ? row.maxTermMonths : null;
  const span = months ? ` on your first ${months === 1 ? "month" : `${months} months`}` : "";
  let headline: string;
  if (row.kind === "PERCENT" && row.value > 0 && row.value <= 100) headline = row.value >= 100 ? `${months === 1 ? "First month" : months ? `First ${months} months` : "Your order"} free` : `${row.value}% off${span}`;
  else if (row.kind === "FIXED_CENTS" && row.value > 0) headline = `${usd(row.value)} off${span}`;
  else if (row.kind === "SET_PRICE_CENTS" && row.value >= 0) headline = `${usd(row.value)} for your first term`;
  else return null;
  const fineprint: string[] = ["Enter the code in the promo field at checkout."];
  if (row.firstTimeOnly) fineprint.push("For a first purchase only.");
  else if (row.excludeActiveCustomers) fineprint.push("For accounts with no active server.");
  if (row.expiresAt) fineprint.push(`Valid until ${row.expiresAt.toISOString().slice(0, 10)}.`);
  return { code: row.code.toUpperCase(), headline, fineprint };
}

// ── the Cyrus tokens block ──────────────────────────────────────────────────

export type GrantScope = TokenConfig["grant"]["scope"];

/** Does a server of this game family earn tokens under the live scope? (mirrors lib/cyrus/tokens/grants.ts eligible()). */
export function grantApplies(scope: GrantScope, family: string, cyrusLive: boolean): boolean {
  if (scope === "all_servers" || scope === "all_game_servers") return !!family;
  return cyrusLive;
}

export type TokenFacts = {
  /** Tokens on purchase / on each paid renewal, for ONE month of the cheapest plan. */
  initial: number;
  renewal: number;
  /** For the plan the numbers were computed on. */
  basis: { planName: string; monthlyCents: number };
  expiryDays: number;
  perServerCap: number;
};

/**
 * The real grant for the cheapest plan of a game, from the live token settings. null unless the economy is live AND the
 * scope covers the game AND there is a plan. Uses the SAME function the grant code calls (serverGrant), so the page can
 * never promise a different number than the ledger will credit. Larger plans earn more (the formula is per dollar).
 */
export function tokenFacts(cfg: TokenConfig, game: HostGame): TokenFacts | null {
  if (!cfg.live || !grantApplies(cfg.grant.scope, game.family, game.cyrusLive)) return null;
  const p = game.plans[0];
  if (!p) return null;
  const i = serverGrant("initial", p.monthlyCents, 1, cfg);
  const r = serverGrant("renewal", p.monthlyCents, 1, cfg);
  if (!i.tokens) return null;
  return { initial: i.tokens, renewal: r.tokens, basis: { planName: p.name, monthlyCents: p.monthlyCents }, expiryDays: i.expiresInDays, perServerCap: cfg.grant.perServerCap };
}

// ── copy + structured data ──────────────────────────────────────────────────

export type HostCopy = { title: string; description: string; h1: string; lead: string };

const listJoin = (xs: string[]) => (xs.length <= 1 ? xs.join("") : xs.length === 2 ? xs.join(" and ") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);

export function hostCopy(r: NonNullable<HostRoute>, cat: HostCatalog): HostCopy {
  const from = (g: HostGame) => (g.fromMonthlyCents != null ? ` from ${usd(g.fromMonthlyCents)}/mo` : "");
  if (r.kind === "game") {
    const mods = r.game.cyrusLive ? " Install Cyrus mods in one click." : "";
    return {
      title: `${r.game.name} server hosting${from(r.game)} | Cyrus x Nxeon`,
      description: `${r.game.name} server hosting on Nxeon${from(r.game)}. Pick your location, deploy from your dashboard.${mods}`.replace(/\s+/g, " ").trim(),
      h1: `${r.game.name} server hosting`,
      lead: r.game.cyrusLive ? "Run your server on Nxeon and add Cyrus-built mods without touching a file." : "Deploy from your dashboard and pick where it runs.",
    };
  }
  if (r.kind === "location") {
    return {
      title: `Game server hosting in ${r.loc.name} | Cyrus x Nxeon`,
      description: `Game servers hosted in ${r.loc.name} on Nxeon. ${cat.games.length} games, one dashboard.`,
      h1: `Game server hosting in ${r.loc.name}`,
      lead: `Servers that run in ${r.loc.name}, deployed from one dashboard.`,
    };
  }
  if (r.kind === "combo") {
    return {
      title: `${r.game.name} server hosting in ${r.loc.name}${from(r.game)} | Cyrus x Nxeon`,
      description: `${r.game.name} server hosting in ${r.loc.name} on Nxeon${from(r.game)}.${r.game.cyrusLive ? " Install Cyrus mods in one click." : ""}`.trim(),
      h1: `${r.game.name} server hosting in ${r.loc.name}`,
      lead: `Your ${r.game.name} server runs in ${r.loc.name}.${r.game.cyrusLive ? " Add mods made with Cyrus in one click." : ""}`,
    };
  }
  const names = cat.locations.map((l) => l.name);
  return {
    title: "Game server hosting with Nxeon | Cyrus",
    description: `Host your game server with Nxeon${names.length ? ` in ${listJoin(names)}` : ""}, and install mods made with Cyrus in one click.`,
    h1: "Host your game server with Nxeon",
    lead: "Pick a game, pick a place. Cyrus mods install in one click.",
  };
}

export type HostFaq = { q: string; a: string };

/** FAQ entries that are visible on the page and true by construction (no latency, uptime or player claims). */
export function hostFaq(r: NonNullable<HostRoute>, cat: HostCatalog, facts: { coupon: CouponFacts | null; tokens: TokenFacts | null }): HostFaq[] {
  const out: HostFaq[] = [];
  const g = r.kind === "game" || r.kind === "combo" ? r.game : null;
  if (g?.cyrusLive) {
    out.push({ q: "How do Cyrus mods install?", a: "Open a mod's page, press Install on my Nxeon server, choose your server and confirm. Nxeon adds the plugin to the server for you; you do not upload files." });
  }
  if (r.kind === "game" || r.kind === "combo") {
    out.push({ q: "Where can I run it?", a: cat.locations.length ? `You choose the location at checkout: ${listJoin(cat.locations.map((l) => l.name))}.` : "You choose the location at checkout." });
  }
  if (facts.coupon) out.push({ q: `How do I use the code ${facts.coupon.code}?`, a: `Enter ${facts.coupon.code} in the promo code field when you order. ${facts.coupon.headline}.${facts.coupon.fineprint.slice(1).length ? " " + facts.coupon.fineprint.slice(1).join(" ") : ""}` });
  if (facts.tokens) out.push({ q: "What are Cyrus tokens?", a: "Tokens are what Cyrus spends when it builds a mod for you. A paid server includes some when you buy it and again on each paid renewal." });
  return out.slice(0, 5);
}

export const faqJsonLd = (items: HostFaq[]) =>
  items.length ? { "@context": "https://schema.org", "@type": "FAQPage", mainEntity: items.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })) } : null;

