// Server half of the hosting cross-sell pages: reads the live catalogue (plans, enabled node regions), the live coupon row
// and the live token settings, then hands them to the pure builders in ./hosting.ts. Read-only. Never throws: a failed
// source contributes nothing (absent beats wrong). Cached 5 minutes per process (catalogue rows change rarely).
import { db } from "../db";
import { getSetting, getSettingBool } from "../settings";
import { GAME_DISPLAY } from "../games";
import { GAME_URL_SLUG } from "../marketing/gameLocationLandings";
import { CUSTOMER_REGION_LABELS, REGION_COUNTRY } from "../node-regions";
import { earnsCyrusTokens } from "../cyrus/tokens/games";
import { loadTokenConfig } from "../cyrus/tokens/config";
import { buildGames, buildLocations, couponFacts, tokenFacts, type CouponFacts, type HostCatalog, type HostGame, type TokenFacts, type IndexPolicyInput } from "./hosting";

export const HOST_COUPON_KEY = "cyrus_host_coupon_code";
export const HOST_COUPON_DEFAULT = "CYRUS";
export const CONTENT_INDEX_KEY = "cyrus_content_index_enabled";
export const HOST_INDEX_GAMES_KEY = "cyrus_host_index_games";

let cache: { at: number; cat: HostCatalog } | null = null;
const TTL = 5 * 60_000;

export async function loadHostCatalog(fresh = false): Promise<HostCatalog> {
  if (!fresh && cache && Date.now() - cache.at < TTL) return cache.cat;
  const [plans, nodes] = await Promise.all([
    db.gamePlan.findMany({ where: { active: true }, select: { id: true, gameFamily: true, name: true, ramMB: true, cpuCores: true, diskGB: true, slots: true, priceCents: true, termMonths: true } }).catch(() => []),
    db.node.findMany({ where: { enabled: true }, select: { region: true }, distinct: ["region"] }).catch(() => []),
  ]);
  const names: Record<string, string> = {};
  const slugs: Record<string, string> = {};
  for (const [fam, d] of Object.entries(GAME_DISPLAY)) names[fam] = d.name;
  for (const [fam, s] of Object.entries(GAME_URL_SLUG)) slugs[fam] = s;
  const cat: HostCatalog = {
    games: buildGames(plans, { names, slugs, cyrusLive: (f) => earnsCyrusTokens(f) }),
    locations: buildLocations(nodes.map((n) => n.region), (r) => CUSTOMER_REGION_LABELS[r] ?? r, (r) => REGION_COUNTRY[r]),
  };
  cache = { at: Date.now(), cat };
  return cat;
}

export async function loadCoupon(now = new Date()): Promise<CouponFacts | null> {
  try {
    const code = ((await getSetting(HOST_COUPON_KEY, HOST_COUPON_DEFAULT)).trim() || HOST_COUPON_DEFAULT).toUpperCase().slice(0, 32);
    if (!/^[A-Z0-9_-]{2,32}$/.test(code)) return null;
    const row = await db.coupon.findUnique({ where: { code }, select: { code: true, kind: true, value: true, scope: true, serviceKind: true, planSlug: true, maxTermMonths: true, firstTimeOnly: true, excludeActiveCustomers: true, maxRedemptions: true, timesRedeemed: true, expiresAt: true, active: true, trialDays: true } });
    return couponFacts(row, now);
  } catch {
    return null;
  }
}

export async function loadTokenFacts(game: HostGame): Promise<TokenFacts | null> {
  try {
    return tokenFacts(await loadTokenConfig(), game);
  } catch {
    return null;
  }
}

export async function loadIndexPolicy(): Promise<IndexPolicyInput> {
  const [on, allow] = await Promise.all([getSettingBool(CONTENT_INDEX_KEY, false).catch(() => false), getSetting(HOST_INDEX_GAMES_KEY, "").catch(() => "")]);
  return { indexingOn: on, allowFamilies: allow.split(",").map((s) => s.trim().toLowerCase()).filter((s) => /^[a-z0-9]{2,40}$/.test(s)).slice(0, 20) };
}
