  const v = validatePick({ id: pageId, kind: str(fd, "kind", 10), reason: str(fd, "reason", 400), order: str(fd, "order", 6), startsAt, endsAt }, new Date());
  if (!v.ok) go(fd, "err", v.error);
  const before = parseSpotlight(await settingValue(SPOTLIGHT_KEY));
  const next = upsertPick(before, v.pick);
  if (!next.ok) go(fd, "err", next.error);
  await setOrClear(SPOTLIGHT_KEY, JSON.stringify(next.list));
  await cyrusAudit({ actorId: admin.id, action: "spotlight.edit", target: `page:${page.slug}`, before: before.find((p) => p.id === pageId && p.kind === v.pick.kind) ?? null, after: v.pick });
  go(fd, "ok", `“${page.title}” is now a ${v.pick.kind === "week" ? "Mod of the week" : "Staff pick"}.`);
}

export async function adminCyrusSpotlightRemove(fd: FormData) {
  const admin = await guard("spotlight.edit");
  const pageId = str(fd, "pageId", 40);
  const kind = str(fd, "kind", 10);
  if (kind !== "week" && kind !== "staff") go(fd, "err", "Bad pick.");
  const { SPOTLIGHT_KEY, parseSpotlight, removePick } = await import("./cyrus-site/spotlight");
  const before = parseSpotlight(await settingValue(SPOTLIGHT_KEY));
  const next = removePick(before, pageId, kind);
  if (next.length === before.length) go(fd, "ok", "No change.");
  await setOrClear(SPOTLIGHT_KEY, next.length ? JSON.stringify(next) : null);
  await cyrusAudit({ actorId: admin.id, action: "spotlight.edit", target: `page:${pageId}`, before: before.find((p) => p.id === pageId && p.kind === kind) ?? null, after: null });
  go(fd, "ok", "Pick removed.");
}

/** Mark an account as the Cyrus team's (its public mods show "Made by the Cyrus team"), or take it back. */
export async function adminCyrusOfficialAuthor(fd: FormData) {
  const admin = await guard("official.set");
  const on = fd.get("on") === "1";
  const userId = str(fd, "userId", 64);
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(userId)) go(fd, "err", "Bad account.");
  if (!(await db.user.findUnique({ where: { id: userId }, select: { id: true } }))) go(fd, "err", "No such account.");
  const { OFFICIAL_KEY, parseOfficialIds } = await import("./cyrus-site/official");
  const before = parseOfficialIds(await settingValue(OFFICIAL_KEY));
  const next = on ? [...new Set([...before, userId])].slice(0, 20) : before.filter((x) => x !== userId);
  if (next.join() === before.join()) go(fd, "ok", "No change.");
  await setOrClear(OFFICIAL_KEY, next.length ? JSON.stringify(next) : null);
  await cyrusAudit({ actorId: admin.id, action: "official.set", target: `user:${userId}`, before: { official: before.includes(userId) }, after: { official: on } });
  go(fd, "ok", on ? "Account marked as the Cyrus team." : "Account is no longer shown as the Cyrus team.");
}

