// Small server-safe building blocks for /admin/cyrus. Uses only the admin portal's shared classes
// (card, btn-*, input, Badge), so dark and light both come from app/admin/admin-shell.css.
import Link from "next/link";
import { Badge } from "@/components/ui/primitives";

export const n = (x: number | null | undefined) => (x === null || x === undefined || !Number.isFinite(x) ? "–" : Math.round(x).toLocaleString("en-US"));
export const usd = (x: number | null | undefined, d = 2) => (x === null || x === undefined || !Number.isFinite(x) ? "–" : `${x < 0 ? "-" : ""}$${Math.abs(x).toFixed(d)}`);
export const pct = (x: number | null | undefined) => (x === null || x === undefined || !Number.isFinite(x) ? "–" : `${Math.round(x * 100)}%`);
export const secs = (ms: number | null | undefined) => (!ms ? "–" : ms < 60_000 ? `${Math.round(ms / 1000)}s` : `${(ms / 60_000).toFixed(1)}m`);
export const when = (d: Date | string | null | undefined) => (d ? new Date(d).toISOString().replace("T", " ").slice(0, 16) + " UTC" : "–");

export function Flash({ sp }: { sp: Record<string, string | string[] | undefined> }) {
  const ok = typeof sp.ok === "string" ? sp.ok : null;
  const err = typeof sp.err === "string" ? sp.err : null;
  if (!ok && !err) return null;
  return (
    <p role="status" className={`mb-4 rounded-lg border px-3 py-2 text-sm ${err ? "border-red-500/30 bg-red-500/10 text-red-300" : "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"}`}>
      {err ?? ok}
    </p>
  );
}

export function Section({ title, sub, children, right, id }: { title: string; sub?: React.ReactNode; children: React.ReactNode; right?: React.ReactNode; id?: string }) {
  return (
    <section id={id} className="card mb-6 min-w-0">
      <div className="mb-3 flex flex-wrap items-start justify-between gap-2">
        <div className="min-w-0">
          <h2 className="text-sm font-semibold">{title}</h2>
          {sub ? <p className="mt-0.5 text-xs text-slate-400">{sub}</p> : null}
        </div>
        {right}
      </div>
      {children}
    </section>
  );
}

/** Honest empty state: says WHY there is nothing (no data yet, or which merge it waits for). */
export function Empty({ children, waitsFor }: { children: React.ReactNode; waitsFor?: string }) {
  return (
    <div className="rounded-lg border border-dashed border-white/10 px-4 py-6 text-center text-sm text-slate-400" data-empty>
      <p>{children}</p>
      {waitsFor ? <p className="mt-1 text-xs text-slate-500">Arrives with the <span className="font-mono">{waitsFor}</span> merge.</p> : null}
    </div>
  );
}

