  const can = { pick: canCyrusAdmin(me.role, "spotlight.edit"), official: canCyrusAdmin(me.role, "official.set") };
  const now = new Date();
  const [raw, legacy, popularOn, official, { cards }, pages] = await Promise.all([
    getSetting(SPOTLIGHT_KEY, "").catch(() => ""),
    readFeaturedIds().catch(() => [] as string[]),
    getSettingBool(SPOTLIGHT_POPULAR_KEY, false).catch(() => false),
    officialUserIds(),
    loadSiteMods({ take: 100 }),
    cyrusDb.cyrusModPage.findMany({ where: { visibility: "PUBLIC", hiddenAt: null }, select: { id: true, slug: true, title: true, userId: true } , take: 300 }),
  ]);
  const picks = parseSpotlight(raw);
  const byId = new Map(cards.map((c) => [c.id, c]));
  const titleOf = (id: string) => byId.get(id)?.title ?? pages.find((p) => p.id === id)?.title ?? id;
  const live = picks.filter((p) => pickState(p, now) === "live");
  const scheduled = picks.filter((p) => pickState(p, now) === "scheduled");
