        <StatCard label="Public mods" value={n(pages.length)} />
        <StatCard label="Past a minimum sample" value={n(scored.length)} delta={`needs ${n(3)} for "Popular"`} deltaGood={scored.length >= 3} />
        <StatCard label="Popular right now" value={popularOn ? "ON" : "OFF"} />
