            <span />
            <label className="text-xs text-slate-400">Starts (UTC, optional)
              <input name="startsAt" type="datetime-local" className="input mt-1 w-full" />
            </label>
            <label className="text-xs text-slate-400">Ends (UTC, optional)
              <input name="endsAt" type="datetime-local" className="input mt-1 w-full" />
            </label>
            <div className="sm:col-span-2"><button className="btn-primary text-sm">Save pick</button></div>
          </form>
        ) : <Empty>Your role can read this page but not change picks.</Empty>}
      </Section>

      <Section title="Current picks" sub="Live, scheduled and ended picks, in the order the public page uses.">
        {picks.length === 0 ? <Empty>No picks yet. The public Spotlight sections stay hidden (or show an honest &quot;nothing yet&quot;) until one is live.</Empty> : (
