                  const c = byId.get(p.id);
                  const st = pickState(p, now);
                  return (
                    <tr key={`${p.kind}:${p.id}`} className={tdRow}>
                      <td>{c ? <Link className="underline" href={`/mods/${c.slug}`}>{c.title}</Link> : <span className="text-amber-300">{titleOf(p.id)} (not public)</span>}</td>
                      <td><Badge tone={p.kind === "week" ? "violet" : "blue"}>{p.kind === "week" ? "Mod of the week" : "Staff pick"}</Badge> <span className="text-xs text-slate-500">#{p.order}</span></td>
                      <td><Badge tone={st === "live" ? "green" : st === "scheduled" ? "amber" : "slate"}>{st}</Badge></td>
                      <td className="max-w-[280px] break-words">{p.reason}</td>
                      <td className="whitespace-nowrap text-xs text-slate-400">{p.startsAt ? when(p.startsAt) : "from now"}<br />{p.endsAt ? `to ${when(p.endsAt)}` : "no end"}</td>
                      <td className="text-xs text-slate-400">{c ? <>{c.views === null ? "views n/a" : c.views > 0 ? `${n(c.views)} views` : "no views yet"} · {c.installers > 0 ? `${n(c.installers)} installer(s)` : "no installs yet"} · {ratingText(c.rating)}</> : "–"}</td>
                      <td className="text-right">
                        {can.pick ? (
                          <form action={adminCyrusSpotlightRemove}><Hidden name="back" value={BACK} /><Hidden name="pageId" value={p.id} /><Hidden name="kind" value={p.kind} /><button className="btn-secondary text-xs">Remove</button></form>
                        ) : null}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </TableWrap>
        )}
      </Section>

      <Section title="Real signals" sub={`Counted, never set. A signal only counts past a minimum sample (${SIGNAL_MIN.views7d} views in 7 days, ${SIGNAL_MIN.installers} installing accounts, or ${SIGNAL_MIN.ratings} ratings). "Popular right now" needs the switch (Settings: ${SPOTLIGHT_POPULAR_KEY}) and at least 3 qualifying mods.`}>
        {cards.length === 0 ? <Empty>No public mods yet, so no counters exist.</Empty> : (
          <TableWrap>
            <table className="w-full text-sm">
              <thead><tr className={thCls}><th>Mod</th><th>Views total</th><th>Views 7d</th><th>Installing accounts</th><th>Ratings</th><th>Past sample</th></tr></thead>
              <tbody>
                {cards.map((c) => (
                  <tr key={c.id} className={tdRow}>
                    <td>{c.title}</td>
                    <td>{c.views === null ? "n/a (table not applied)" : n(c.views)}</td>
                    <td>{c.views7d === null ? "n/a" : n(c.views7d)}</td>
                    <td>{n(c.installers)}</td>
                    <td>{ratingText(c.rating)}</td>
                    <td>{meetsSample({ views7d: c.views7d, installers: c.installers, ratings: c.rating }) ? <Badge tone="green">yes</Badge> : <span className="text-slate-500">not yet</span>}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </TableWrap>
        )}
      </Section>

      <Section title="Official author accounts" sub={'Accounts shown as "Made by the Cyrus team" with the staff badge. Use it only for mods Cyrus itself built; never for anyone else.'} id="official">
        {authors.length === 0 ? <Empty>No account has a public mod yet.</Empty> : (
          <TableWrap>
            <table className="w-full text-sm">
              <thead><tr className={thCls}><th>Account</th><th>Author tag</th><th>Public mods</th><th>Official</th><th /></tr></thead>
              <tbody>
                {authors.map((uid) => {
                  const isOff = official.includes(uid);
                  return (
                    <tr key={uid} className={tdRow}>
                      <td className="max-w-[240px] truncate"><UserLink id={uid} email={emails.get(uid)} /></td>
                      <td>{authorTag.get(uid)}</td>
                      <td>{pages.filter((p) => p.userId === uid).length}</td>
                      <td>{isOff ? <Badge tone="green">Cyrus team</Badge> : <span className="text-slate-500">no</span>}</td>
                      <td className="text-right">
                        {can.official ? (
                          <form action={adminCyrusOfficialAuthor}><Hidden name="back" value={BACK} /><Hidden name="userId" value={uid} /><Hidden name="on" value={isOff ? "0" : "1"} /><button className="btn-secondary text-xs">{isOff ? "Remove badge" : "Mark as Cyrus team"}</button></form>
                        ) : null}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </TableWrap>
        )}
      </Section>
    </div>
  );
}
