// Public spotlight for the cyrus.my landing generator and the content pages: the editorial "Mod of the week" and "Staff
// picks" (lib/cyrus-site/spotlight.ts), nothing else. EDITORIAL + REAL: a rating is the real average of other accounts'
// ratings or null (the reader prints "New"); no counter is ever backfilled. Same gate as /api/cyrus/featured: 404 until
// cyrus_mods_public_enabled. Cacheable for 5 minutes. No account ids, no emails.
import { NextResponse } from "next/server";
import { cyrusModsPublicEnabled } from "@/lib/cyrus-mods/gate";
import { loadSpotlight, type SpotlightCard } from "@/lib/cyrus-site/mods.server";

export const dynamic = "force-dynamic";

const pub = (c: SpotlightCard) => ({
  slug: c.slug, title: c.title, tagline: c.tagline, creator: c.author, official: c.official,
  game: c.game, gameVersion: c.mcVersions[0] ?? null, version: c.version,
  rating: c.rating.count > 0 ? c.rating.average : null, ratings: c.rating.count,
  badge: c.badge, reason: c.reason, until: c.until, iconUrl: c.iconUrl,
});

export async function GET() {
  if (!(await cyrusModsPublicEnabled())) return new NextResponse("Not found", { status: 404 });
  const s = await loadSpotlight();
  const thisWeek = s.thisWeek.map(pub);
  const staffPicks = s.staffPicks.map(pub);
  // `cards` keeps the shape apps/cyrus-site/featured.mjs already reads (the headline mod first, then the staff picks)
  const seen = new Set<string>();
  const cards = [...thisWeek, ...staffPicks].filter((c) => (seen.has(c.slug) ? false : (seen.add(c.slug), true)));
  return NextResponse.json({ modOfWeek: thisWeek[0] ?? null, thisWeek, staffPicks, cards }, { headers: { "Cache-Control": "public, max-age=300, s-maxage=300" } });
}
