/**
 * Public list-route guard (2026-10-15 incident hardening).
 *
 * A distributed scraper walked /mods?sort=latest&page=8000+ (deep OFFSET
 * pagination: Postgres sorts+skips tens of thousands of rows per request) from
 * many IPs and took the site down. Everything here is PURE and edge-safe (no
 * node:* imports) so middleware.ts can use it before any page renders:
 *
 *   - MAX_PUBLIC_PAGE: no human or search engine pages past this on a catalogue.
 *     Above it the request is answered 404 in the edge layer, with zero DB work.
 *   - listRateLimit: per-IP sliding window for list-shaped URLs (a query string
 *     with page/q/sort/filter keys). In-memory, per process, bounded.
 *
 * The nginx equivalents (deploy/nginx/nxeon-list-guard.conf) stop the traffic
 * one hop earlier; this is the defence that travels with the code.
 */

/** Highest `page` a public list route will serve. 100 x 24 = 2,400 rows deep. */
export const MAX_PUBLIC_PAGE = Math.max(1, Number(process.env.NXEON_MAX_PUBLIC_PAGE ?? 100) || 100);
/** Highest raw `offset`/`skip`/`start` value a public route will accept. */
export const MAX_PUBLIC_OFFSET = MAX_PUBLIC_PAGE * 25;

const PAGE_KEYS = ["page", "p", "pg"];
const OFFSET_KEYS = ["offset", "skip", "start"];
/** Query keys that make a URL a "list/search/filter" request worth rate limiting. */
const LIST_KEYS = new Set([...PAGE_KEYS, ...OFFSET_KEYS, "q", "query", "search", "sort", "category", "loader", "version", "filter", "cursor", "tag"]);

/** Paths that are authenticated surfaces: not guarded here (their own auth + clamps apply). */
const PRIVATE_PREFIXES = ["/admin", "/staff", "/dashboard", "/api/", "/_next", "/sso", "/login"];

export function isGuardedListPath(pathname: string): boolean {
  if (/\.[a-z0-9]{2,5}$/i.test(pathname)) return false;
  return !PRIVATE_PREFIXES.some((p) => pathname === p || pathname.startsWith(p.endsWith("/") ? p : p + "/"));
}

/** First finite integer value of any of `keys`, or null. Non-numeric junk counts as 1 (harmless, clamps to page 1). */
function intParam(sp: URLSearchParams, keys: string[]): number | null {
  for (const k of keys) {
    const vals = sp.getAll(k);
    if (!vals.length) continue;
    let max = 1;
    for (const v of vals) {
      const n = Number(v);
      if (Number.isFinite(n)) max = Math.max(max, Math.floor(n));
      // "1e9", "9".repeat(30) etc. parse to huge finite or Infinity: treat Infinity as huge
      else if (/^\s*\+?infinity\s*$/i.test(v)) max = Number.MAX_SAFE_INTEGER;
    }
    return max;
  }
  return null;
}

export type GuardVerdict = { block: false } | { block: true; status: 404 | 429; reason: string; retryAfterSec?: number };

/** Is this URL asking for an offset the catalogue should never serve? */
export function deepPaginationVerdict(pathname: string, sp: URLSearchParams): GuardVerdict {
  if (!isGuardedListPath(pathname)) return { block: false };
  const page = intParam(sp, PAGE_KEYS);
  if (page !== null && page > MAX_PUBLIC_PAGE) return { block: true, status: 404, reason: "page-too-deep" };
  const off = intParam(sp, OFFSET_KEYS);
  if (off !== null && off > MAX_PUBLIC_OFFSET) return { block: true, status: 404, reason: "offset-too-deep" };
  return { block: false };
}

export function isListShapedRequest(pathname: string, sp: URLSearchParams): boolean {
  if (!isGuardedListPath(pathname)) return false;
  for (const k of sp.keys()) if (LIST_KEYS.has(k)) return true;
  return false;
}

// ── per-IP sliding window (bounded) ────────────────────────────────────────────
export const LIST_RATE_MAX = Math.max(1, Number(process.env.NXEON_LIST_RATE_MAX ?? 90) || 90);
export const LIST_RATE_WINDOW_MS = 60_000;
const MAX_BUCKETS = 20_000;

type Bucket = number[];
const g = globalThis as unknown as { __nxeonListRate?: Map<string, Bucket> };
const buckets: Map<string, Bucket> = (g.__nxeonListRate ??= new Map());

/** Test hook. */
export function resetListRateLimit(): void {
  buckets.clear();
}

export function listRateLimit(ip: string, now = Date.now(), max = LIST_RATE_MAX, windowMs = LIST_RATE_WINDOW_MS): { ok: boolean; retryAfterSec: number } {
  const key = ip || "unknown";
  const cutoff = now - windowMs;
  const hits = (buckets.get(key) ?? []).filter((t) => t > cutoff);
  if (hits.length >= max) {
    buckets.set(key, hits);

