// Small server-rendered building blocks for the Cyrus content pages. No client JS. Every number printed here comes from
// a real input; absent inputs print nothing or "New". Styles: app/(cyrus-web)/cyrus-web/web.css (prefix cw-).
import type { ReactNode } from "react";
import { safeJsonLd } from "@/lib/cyrus-mods/seo";
import { ART_BASE, COVER_ALT, SCENE_ALT, coverFor, type SceneName } from "@/lib/cyrus-site/art";
import { OFFICIAL_BADGE } from "@/lib/cyrus-site/official";
import { ratingText } from "@/lib/cyrus-site/spotlight";
import type { SiteModCard, SpotlightCard } from "@/lib/cyrus-site/mods.server";

export function JsonLd({ items }: { items: Array<unknown | null | undefined> }) {
  return (
    <>
      {items.filter(Boolean).map((it, i) => (
        <script key={i} type="application/ld+json" dangerouslySetInnerHTML={{ __html: safeJsonLd(it) }} />
      ))}
    </>
  );
}

/** AVIF -> WebP -> JPEG, with the intrinsic size so nothing shifts. `sm` = the 800 px variant. */
export function Scene({ name, alt, sm = false, priority = false, className = "" }: { name: SceneName; alt?: string; sm?: boolean; priority?: boolean; className?: string }) {
  const f = `${ART_BASE}/${name}${sm ? "-sm" : ""}`;
  const [w, h] = sm ? [800, 450] : [1600, 900];
  return (
    <picture>
      <source srcSet={`${f}.avif`} type="image/avif" />
      <source srcSet={`${f}.webp`} type="image/webp" />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={`${f}.jpg`} alt={alt ?? SCENE_ALT[name]} width={w} height={h} className={className} loading={priority ? "eager" : "lazy"} decoding="async" {...(priority ? { fetchPriority: "high" as const } : {})} />
    </picture>
  );
}

export function ModCover({ slug, coverUrl, alt, className = "" }: { slug: string; coverUrl: string | null; alt: string; className?: string }) {
  if (coverUrl) {
    // eslint-disable-next-line @next/next/no-img-element
    return <img src={coverUrl} alt={alt} width={640} height={360} className={className} loading="lazy" decoding="async" />;
  }
  const n = coverFor(slug);
  const f = `${ART_BASE}/cover-${n}-sm`;
  return (
    <picture>
      <source srcSet={`${f}.webp`} type="image/webp" />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={`${f}.jpg`} alt={COVER_ALT} width={600} height={315} className={className} loading="lazy" decoding="async" />
    </picture>
  );
}

export function AuthorTag({ name, official, className = "" }: { name: string; official: boolean; className?: string }) {
  return (
    <span className={`cw-author ${className}`}>
      <span>by {name}</span>
      {official ? <span className="cw-badge cw-badge-staff" title="Made by the Cyrus team">{OFFICIAL_BADGE}</span> : null}
    </span>
  );
}

/** Real counters in one line. Zero or unknown = "New". Never a placeholder number. */
export function Counters({ card }: { card: Pick<SiteModCard, "views" | "installers" | "rating" | "stars"> }) {
  const bits: string[] = [];
  if (card.installers > 0) bits.push(`${card.installers.toLocaleString("en-US")} ${card.installers === 1 ? "server account" : "server accounts"}`);
  if ((card.views ?? 0) > 0) bits.push(`${(card.views ?? 0).toLocaleString("en-US")} ${card.views === 1 ? "view" : "views"}`);
  if (card.stars > 0) bits.push(`${card.stars.toLocaleString("en-US")} ${card.stars === 1 ? "star" : "stars"}`);
  const rated = card.rating.count > 0;
  return (
    <span className="cw-counters">
      {bits.length ? bits.join(" · ") : <span className="cw-new">New</span>}
      {rated ? <> · <span title="Average of ratings from accounts that installed it">{ratingText(card.rating)}</span></> : null}
    </span>
  );
}

export function ModCard({ card, href, spot }: { card: SiteModCard; href: string; spot?: Pick<SpotlightCard, "badge" | "reason"> | null }) {
  return (
    <article className="cw-card cw-mod">
      <a href={href} className="cw-mod-cover" aria-label={card.title}>
        <ModCover slug={card.slug} coverUrl={card.coverUrl} alt={card.coverAlt} />
        {spot ? <span className={`cw-badge ${spot.badge === "Mod of the week" ? "cw-badge-week" : "cw-badge-pick"}`}>{spot.badge}</span> : null}
