// Content pages (games / mods / host / blog): the request context and the gates, SERVER ONLY.
//
// Visibility (fail CLOSED, a plain 404 like the help center):
//   content pages (games, host, blog)  Setting cyrus_content_public_enabled, or a private-preview account
//   mod pages and mod lists            Setting cyrus_mods_public_enabled (the existing launch flag), or a preview account
// Indexing is a SEPARATE decision (Setting cyrus_content_index_enabled for content pages; the mods flag for mod pages) and
// the pages are noindex on every host except the Cyrus host. Each page calls its gate itself; nothing trusts the layout.
import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { currentUser, onCyrusHost } from "@/lib/auth";
import { getSettingBool } from "@/lib/settings";
import { isPreviewUser } from "@/lib/preview-access";
import { cyrusModsPublicEnabled } from "@/lib/cyrus-mods/gate";
import { cyrusSiteOrigin, cyrusPageMetadata } from "@/lib/cyrus/seo";
import { webHref } from "@/lib/cyrus-site/web-paths";

export const CONTENT_PUBLIC_KEY = "cyrus_content_public_enabled";
export const CONTENT_INDEX_KEY = "cyrus_content_index_enabled";

export type WebCtx = {
  onCyrus: boolean;
  origin: string;
  signedIn: boolean;
  /** the owner's launch switches, as set */
  contentPublic: boolean;
  modsPublic: boolean;
  indexOn: boolean;
  preview: boolean;
  /** may this viewer see the content pages / the mod pages at all */
  contentOn: boolean;
  modsOn: boolean;
  /** link to a public path from here (public path on the Cyrus host, the internal one elsewhere) */
  href: (path: string) => string;
  /** where "Open Cyrus" goes */
  openCyrus: string;
};

export async function webCtx(): Promise<WebCtx> {
  const [onCyrus, user, contentPublic, modsPublic, indexOn] = await Promise.all([
    onCyrusHost(),
    currentUser().catch(() => null),
    getSettingBool(CONTENT_PUBLIC_KEY, false).catch(() => false),
    cyrusModsPublicEnabled(),
    getSettingBool(CONTENT_INDEX_KEY, false).catch(() => false),
  ]);
  const preview = !(contentPublic && modsPublic) ? await isPreviewUser(user, "modbuilder").catch(() => false) : false;
  return {
    onCyrus, origin: cyrusSiteOrigin(), signedIn: !!user,
    contentPublic, modsPublic, indexOn, preview,
    contentOn: contentPublic || preview, modsOn: modsPublic || preview,
    href: (p) => webHref(onCyrus, p),
    openCyrus: onCyrus ? "/home" : "/dashboard/cyrus/app",
  };
}

export async function requireContent(): Promise<WebCtx> {
  const c = await webCtx();
  if (!c.contentOn) notFound();
  return c;
}
export async function requireMods(): Promise<WebCtx> {
  const c = await webCtx();
  if (!c.modsOn) notFound();
  return c;
}

/**
 * Metadata for a content page. `want` = this page passes its own quality bar. A page is indexable only when ALL of:
 * it is served on the Cyrus host, its surface is public (not just a preview), the indexing switch is on (content pages),
 * and `want`. Otherwise noindex,nofollow with no canonical (cyrusPageMetadata), exactly like the other Cyrus pages.
 */
export function webMetadata(c: WebCtx, o: { path: string; title: string; description: string; want: boolean; surface: "content" | "mods"; image?: string }): Metadata {
  const surfaceOk = o.surface === "content" ? c.contentPublic && c.indexOn : c.modsPublic;
  const index = c.onCyrus && surfaceOk && o.want;
  const md = cyrusPageMetadata({ path: o.path, title: o.title, description: o.description, index });
  const url = `${c.origin}${o.path === "/" ? "/" : o.path}`;
  const image = o.image ? (o.image.startsWith("http") ? o.image : `${c.origin}${o.image}`) : undefined;
  return {
    ...md,
    alternates: index ? { canonical: url } : {},
    ...(index ? {
      openGraph: { type: "website", siteName: "Cyrus", title: o.title, description: o.description, url, ...(image ? { images: [{ url: image }] } : {}) },
      twitter: { card: "summary_large_image", title: o.title, description: o.description, ...(image ? { images: [image] } : {}) },
    } : {}),
  };
}
