          {card.game}{card.mcVersions[0] ? ` ${card.mcVersions[0]}` : ""}{card.version ? ` · v${card.version.replace(/^v/i, "")}` : ""}
          {card.category ? ` · ${card.category.label}` : ""}
        </p>
        <Counters card={card} />
      </div>
    </article>
  );
}

export function SectionHead({ eyebrow, title, children, right }: { eyebrow?: string; title: ReactNode; children?: ReactNode; right?: ReactNode }) {
  return (
    <div className="cw-sec-head">
      <div>
        {eyebrow ? <div className="cx-eyebrow">{eyebrow}</div> : null}
