.cx-app .cw-art-cover { border-radius: 20px; overflow: hidden; border: 1px solid var(--cx-line); margin: 0 0 26px; }
.cx-app .cw-art-cover img { width: 100%; height: auto; display: block; }
.cx-app .cw-callout { border-radius: 14px; border: 1px solid var(--cx-line-2); background: var(--cx-glass-2); padding: 14px 16px; font-size: 14px; color: var(--cx-ink-2); margin: 0 0 18px; }
.cx-app .cw-callout b { color: var(--cx-ink); }
@media (prefers-reduced-motion: reduce) { .cx-app .cw-mod { transition: none; } .cx-app .cw-mod:hover { transform: none; } }
@media (max-width: 560px) { .cx-app .cw-nav .cw-hide-sm { display: none; } .cx-app .cw-grid { grid-template-columns: 1fr; } }
