  const c = await webCtx();
  if (!c.contentOn && !c.modsOn) notFound();
  return (
    <div className={`cx-app cw-root ${inter.variable} ${space.variable} ${mono.variable}`}>
      <div className="cx-aura" aria-hidden="true" />
      <header className="cw-bar">
        <a className="cw-brand" href={c.onCyrus ? "/" : c.href("/games")} aria-label="Cyrus">
          <CyrusWordmark height={18} />
        </a>
        <nav aria-label="Cyrus" className="cw-nav">
          {c.contentOn ? <a href={c.href("/games")}>Games</a> : null}
          {c.modsOn ? <a href={c.href("/mods")}>Mods</a> : null}
          {c.contentOn ? <a href={c.href("/host")}>Host</a> : null}
          {c.contentOn ? <a href={c.href("/blog")}>Blog</a> : null}
          <a className="cx-btn cx-btn-sm cx-btn-pri" href={c.openCyrus}>Open Cyrus</a>
        </nav>
      </header>
      <main id="cx-main" className="cw-main">{children}</main>
      <footer className="cw-foot">
        <div className="cw-foot-row">
          <span className="cw-by">Cyrus is a <NxeonLogo height={16} /> product</span>
          <a href={`${c.origin}/legal/terms`}>Terms</a>
          <a href={`${c.origin}/legal/privacy`}>Privacy</a>
          {c.contentOn ? <a href={c.href("/blog/rss.xml")}>RSS</a> : null}
        </div>
        <div>Cyrus builds Minecraft plugins today; every other game is coming soon. Not affiliated with Mojang or Microsoft.</div>
      </footer>
    </div>
  );
}
