  const qs = (o: Record<string, string | number | null>) => {
    const p = new URLSearchParams();
    for (const [k, v] of Object.entries(o)) if (v !== null && v !== "") p.set(k, String(v));
    const s = p.toString();
    return c.href("/mods") + (s ? `?${s}` : "");
  };
  const week = spot?.thisWeek ?? [];
  const staff = spot?.staffPicks ?? [];
  const lastPage = Math.max(1, Math.ceil(total / PER));

  return (
    <>
      <JsonLd items={[{ "@context": "https://schema.org", "@type": "CollectionPage", name: "Minecraft mods made with Cyrus", url: `${c.origin}/mods`, isPartOf: { "@type": "WebSite", name: "Cyrus", url: c.origin } }]} />
      <div className="cw-crumb"><a href={c.href("/games")}>Games</a><span>/</span><span>Mods</span></div>
      <h1 className="cx-h1">Mods made with Cyrus</h1>
      <p className="cx-sub">Paper and Purpur plugins. Every page says what the mod does, what it was tested on, and who made it.</p>

      {!filtered && week.length > 0 && (
        <section className="cw-section" aria-label="This week">
          <SectionHead eyebrow="This week" title={week.length === 1 ? "Mod of the week" : "Mods of the week"}>Chosen by the Cyrus team.</SectionHead>
          <div className="cw-grid-3">
            {week.map((m, i) => <ModCard key={m.id} card={m} href={href(m.slug)} spot={i === 0 || week.length > 1 ? m : m} />)}
          </div>
        </section>
      )}

      {!filtered && (
        <section className="cw-section" aria-label="Staff picks">
          <SectionHead eyebrow="Staff picks" title="Picked by the Cyrus team">Chosen by hand, with the reason. Not a ranking.</SectionHead>
          {staff.length > 0 ? (
            <div className="cw-grid">{staff.map((m) => <ModCard key={m.id} card={m} href={href(m.slug)} spot={m} />)}</div>
          ) : (
            <Quiet>No staff picks yet. The first ones appear when the first mods are published.</Quiet>
          )}
        </section>
      )}

      {!filtered && popular.length > 0 && (
        <section className="cw-section" aria-label="Popular right now">
          <SectionHead eyebrow="Popular right now" title="What people are using">Built from real views, installs and ratings, and only shown once enough of them exist.</SectionHead>
          <div className="cw-grid">{popular.map((p) => <ModCard key={p.id} card={p.card} href={href(p.card.slug)} />)}</div>
        </section>
      )}

      <section className="cw-section" aria-label="All mods">
        <SectionHead eyebrow="All mods" title={category ? (allCategories().find((x) => x.id === category)?.label ?? "Mods") : q ? `Results for “${q}”` : "Everything published"} />
        <form className="cw-search" action={c.href("/mods")} method="get" role="search">
          <input type="search" name="q" defaultValue={q} placeholder="Search mods" aria-label="Search mods" maxLength={60} />
          {category ? <input type="hidden" name="category" value={category} /> : null}
          <button className="cx-btn" type="submit">Search</button>
        </form>
        {cats.length > 0 && (
          <div className="cw-chips" style={{ marginTop: 14 }}>
            <a className="cw-chip" href={qs({ q: q || null })} aria-current={!category}>All</a>
            {cats.map((x) => <a key={x.id} className="cw-chip" href={qs({ category: x.id, q: q || null })} aria-current={category === x.id}>{x.label} · {x.count}</a>)}
          </div>
        )}
        <div style={{ marginTop: 18 }}>
          {cards.length > 0 ? (
            <div className="cw-grid">{cards.map((m) => <ModCard key={m.id} card={m} href={href(m.slug)} spot={[...week, ...staff].find((s) => s.id === m.id) ?? null} />)}</div>
          ) : filtered ? (
            <Quiet>Nothing matches that. <a href={c.href("/mods")} style={{ textDecoration: "underline" }}>Clear the filter</a>.</Quiet>
          ) : (
            <Quiet>No mods are published yet. Mods made with Cyrus appear here once their makers publish them.</Quiet>
          )}
        </div>
        {lastPage > 1 && (
          <nav className="cw-chips" style={{ marginTop: 18 }} aria-label="Pages">
            {page > 1 ? <a className="cw-chip" rel="prev" href={qs({ q: q || null, category, page: page - 1 })}>Previous</a> : null}
            <span className="cw-chip" aria-current="true">Page {page} of {lastPage}</span>
            {page < lastPage ? <a className="cw-chip" rel="next" href={qs({ q: q || null, category, page: page + 1 })}>Next</a> : null}
          </nav>
        )}
      </section>
    </>
  );
}
EOF
