import { NextResponse } from "next/server";
import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { join } from "node:path";
import { db } from "@/lib/db";
import { cyrusDb } from "@/lib/cyrus/db";
import { currentUser } from "@/lib/auth";
import { cyrusAccessFor, pageVisibleTo } from "@/lib/cyrus-mods/gate";
import { licenseText, readModDoc } from "@/lib/cyrus-mods/doc";
import { displayUser } from "@/lib/cyrus-mods/pages";
import { authorUser } from "@/lib/cyrus-mods/username-store";
import { serviceBuildId } from "@/lib/cyrus-mods/registry";
import { svcSourceZip } from "@/lib/modbuilder/client";
import { MODBUILD_DIR, readJar } from "@/lib/modbuilder/store";
import { readZip } from "@/lib/mods/archive";
import { writeZip } from "@/lib/mod-autoupdate/zip";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "../../../../_lib/client-ip";

export const dynamic = "force-dynamic";

const NF = () => NextResponse.json({ error: "Not found" }, { status: 404, headers: { "x-robots-tag": "noindex" } });

/**
 * Cyrus mod downloads (gated like the page): ?what=source|jar&build=<id>.
 * Source = the build's source tree from the build service (cached on the
 * primary after the first fetch) plus LICENSE (the page's licence) and
 * NXEON-CYRUS.md (what it is, version, where it came from). Every Cyrus mod is
 * open source; the creator picks the licence (default MIT).
 */
export async function GET(req: Request, { params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  let user = null;
  try { user = await currentUser(); } catch { user = null; }
  if (!(await cyrusAccessFor(user)).allowed) return NF();
  if (!/^[a-z0-9-]{3,60}$/.test(slug)) return NF();
  const page = await cyrusDb.cyrusModPage.findUnique({ where: { slug } });
  if (!page || !pageVisibleTo(page, user)) return NF();
  const doc = readModDoc(page.doc);
  const url = new URL(req.url);
  const buildId = url.searchParams.get("build") || doc?.currentBuildId || "";
  const what = url.searchParams.get("what") === "jar" ? "jar" : "source";
  const v = doc?.versions.find((x) => x.buildId === buildId);
  if (!v) return NF();
  const ip = trustedClientIp(req);
  const rl = checkRateLimit(`cyrusdl:${user?.id ?? ip}`, { max: 30, windowMs: 10 * 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many downloads. Retry in ${rl.retryAfterSec}s.` }, { status: 429 });
  const build = await cyrusDb.modBuild.findUnique({ where: { id: buildId } });
  if (!build || (build.rootBuildId ?? build.id) !== page.rootBuildId || build.status !== "succeeded") return NF();
  const base = (build.pluginName || "plugin").replace(/[^A-Za-z0-9_]/g, "") || "plugin";
  const ver = (build.version || "source").replace(/[^A-Za-z0-9_.-]/g, "");

