import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { headers } from "next/headers";
import { currentUser } from "@/lib/auth";
import { getSettingBool } from "@/lib/settings";
import { loadSiteMod, officialUserIds, type SiteModDetail } from "@/lib/cyrus-site/mods.server";
import { recordModView } from "@/lib/cyrus-site/views";
import { loadCoupon } from "@/lib/cyrus-site/hosting.server";
import { OFFICIAL_LABEL } from "@/lib/cyrus-site/official";
import { ratingText } from "@/lib/cyrus-site/spotlight";
import { AuthorTag, Counters, JsonLd, ModCover, NxeonLogo, Quiet, SectionHead } from "@/components/cyrus/web/parts";
import { requireMods, webCtx, webMetadata } from "../../_ctx";

export const dynamic = "force-dynamic";

const clip = (s: string, n: number) => (s.length <= n ? s : s.slice(0, n - 1).replace(/\s+\S*$/, "") + "…");
const flat = (s: string) => s.replace(/\s+/g, " ").trim();
const day = (iso: string) => new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });

function seoOf(m: SiteModDetail) {
  const ver = m.mcVersions.length ? (m.mcVersions.length === 1 ? m.mcVersions[0] : `${m.mcVersions[m.mcVersions.length - 1]}–${m.mcVersions[0]}`) : "";
  const lead = flat(m.tagline || (m.summary ? m.summary.split(/(?<=[.!?])\s/)[0] : `A Minecraft plugin made with Cyrus.`));
  return {
    title: clip(`${m.title}: Minecraft${ver ? ` ${ver}` : ""} plugin | Cyrus`, 70),
    description: clip(`${lead} Free Minecraft Paper plugin${ver ? ` for ${ver}` : ""}. Made with Cyrus, source included.`, 158),
    ver,
  };
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const { slug } = await params;
  const c = await webCtx();
  const m = c.modsOn ? await loadSiteMod(slug).catch(() => null) : null;
  if (!m) return { title: "Page not found", robots: { index: false, follow: false } };
  const s = seoOf(m);
  return webMetadata(c, { path: `/mods/${m.slug}`, surface: "mods", want: m.indexable, title: s.title, description: s.description, image: m.coverUrl ?? "/cyrus/web/og-mods.jpg" });
}

const Check = ({ ok }: { ok: boolean }) => <span aria-hidden="true" style={{ color: ok ? "var(--cx-ok)" : "var(--cx-warn)" }}>{ok ? "✓" : "•"}</span>;

export default async function ModPage({ params }: { params: Promise<{ slug: string }> }) {
  const c = await requireMods();
  const { slug } = await params;
  const m = await loadSiteMod(slug);
  if (!m) notFound();
  const user = await currentUser().catch(() => null);
  // one real page view per human render, public launch only (a preview account's looks are not views)
  if (c.modsPublic) {
    const ua = (await headers()).get("user-agent");
    await recordModView({ pageId: m.id, userAgent: ua, viewerIsCreator: !!user && user.id === m.ownerUserId });
  }
  const [installOpen, coupon, official] = await Promise.all([
    getSettingBool("cyrus_install_published_enabled", false).catch(() => false),
    loadCoupon().catch(() => null),
    officialUserIds().catch(() => [] as string[]),
  ]);
  void official;
  const seo = seoOf(m);
  const url = `${c.origin}/mods/${m.slug}`;
  const installHref = `/dashboard/nxlabs/cyrus/${m.slug}`;
  const sourceHref = `/api/nxlabs/cyrus/${m.slug}/download?what=source`;
  const cur = m.versions.find((v) => v.current) ?? m.versions[0];
  const faq = [
    ...(m.summary ? [{ q: `What does ${m.title} do?`, a: clip(flat(m.summary), 600) }] : []),
    ...(m.mcVersions.length ? [{ q: `Which Minecraft versions does ${m.title} support?`, a: `It is built for Minecraft ${m.mcVersions.join(", ")} on Paper.` }] : []),
    { q: `How do I install ${m.title}?`, a: installOpen ? "Open Install on my Nxeon server, choose a server and confirm. Nxeon adds the plugin for you; you do not upload files. Anyone can also download the source and the plugin file." : "Download the plugin file and put it in your server's plugins folder, then restart. One-click install on Nxeon servers opens with the public launch." },
    { q: `Is ${m.title} free?`, a: `Yes. It is free to download under the ${m.license} licence, and the source is included. You only pay for the server it runs on.` },
  ];
  const ld = {
    "@context": "https://schema.org", "@type": "SoftwareApplication", name: m.title, url,
    applicationCategory: "GameApplication", operatingSystem: `Minecraft Java Edition (Paper)`,
    ...(cur?.version ? { softwareVersion: cur.version } : {}),
    description: seo.description,
    ...(m.publishedAt ? { datePublished: m.publishedAt } : {}), dateModified: m.updatedAt,
    author: m.official ? { "@type": "Organization", name: OFFICIAL_LABEL.replace("Made by the ", ""), url: c.origin } : { "@type": "Person", name: m.author },
    publisher: { "@type": "Organization", name: "Cyrus", url: c.origin },
    ...(m.coverUrl ? { image: [m.coverUrl.startsWith("http") ? m.coverUrl : `${c.origin}${m.coverUrl}`] } : {}),
    offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
    ...(m.rating.count > 0 && m.rating.average != null ? { aggregateRating: { "@type": "AggregateRating", ratingValue: m.rating.average.toFixed(1), reviewCount: m.rating.count } } : {}),
  };
  const crumbs = { "@context": "https://schema.org", "@type": "BreadcrumbList", itemListElement: [
    { "@type": "ListItem", position: 1, name: "Cyrus", item: c.origin },
    { "@type": "ListItem", position: 2, name: "Mods", item: `${c.origin}/mods` },
    { "@type": "ListItem", position: 3, name: m.title, item: url },
  ] };
  const faqLd = { "@context": "https://schema.org", "@type": "FAQPage", mainEntity: faq.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })) };

  return (
    <>
      {m.indexable ? <JsonLd items={[ld, crumbs, faqLd]} /> : null}
      <div className="cw-crumb"><a href={c.href("/games/minecraft")}>Minecraft</a><span>/</span><a href={c.href("/mods")}>Mods</a><span>/</span><span>{m.title}</span></div>

      <div className="cw-modhero">
        <div>
          <div className="cw-banner"><ModCover slug={m.slug} coverUrl={m.coverUrl} alt={m.coverAlt} /></div>
          <h1 className="cw-title">{m.title}</h1>
          <AuthorTag name={m.author} official={m.official} />
          {m.official ? <p className="cx-faint" style={{ margin: "4px 0 0", fontSize: 12.5 }}>{OFFICIAL_LABEL}: built with Cyrus by us, so you can see what it does first-hand.</p> : null}
          {m.tagline ? <p className="cw-lead">{m.tagline}</p> : null}
          <div className="cw-factrow">
            <span>Minecraft {seo.ver || "Java"}</span>
            {cur?.version ? <span>v{cur.version.replace(/^v/i, "")}</span> : null}
            <span>{m.license} licence</span>
            <span>updated {day(m.updatedAt)}</span>
            {m.category ? <a href={c.href(`/mods?category=${m.category.id}`)} style={{ textDecoration: "underline" }}>{m.category.label}</a> : null}
          </div>
          <p style={{ margin: "10px 0 0" }}><Counters card={m} /></p>
        </div>

        <aside className="cw-card cw-install" aria-label="Install">
          {installOpen ? (
            <a className="cx-btn cx-btn-energy" href={installHref} rel="nofollow"><NxeonLogo height={18} /> Install on my Nxeon server</a>
          ) : (
            <a className="cx-btn" href={sourceHref} rel="nofollow">Download the source</a>
          )}
          <ol className="cw-steps">
            <li>Press the button and sign in to Nxeon.</li>
            <li>Choose which of your servers gets it.</li>
            <li>Confirm. Nxeon adds the plugin and restarts it for you. No files to upload.</li>
          </ol>
          {!installOpen ? <p className="cx-faint" style={{ margin: 0, fontSize: 12.5 }}>One-click install opens with the public launch. The plugin file and its source can be downloaded now.</p> : null}
          <p className="cx-faint" style={{ margin: 0, fontSize: 12.5 }}>Rating: {ratingText(m.rating)}. Ratings come only from accounts that installed it.</p>
        </aside>
      </div>

      {m.summary ? (
        <section className="cw-section">
          <SectionHead eyebrow="Overview" title={`What ${m.title} does`} />
          <div className="cw-prose"><p>{m.summary}</p></div>
          {m.descriptionHtml ? <div className="cw-prose" dangerouslySetInnerHTML={{ __html: m.descriptionHtml }} /> : null}
        </section>
      ) : null}

      {m.photos.length > 0 ? (
        <section className="cw-section">
          <SectionHead eyebrow="Screenshots" title="In the game" />
          <div className="cw-gallery">
            {m.photos.map((p, i) => (
              <figure key={i}>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={p.url} alt={p.caption || `${m.title}, screenshot ${i + 1}`} loading="lazy" decoding="async" width={p.width ?? 640} height={p.height ?? 360} />
                {p.caption ? <figcaption>{p.caption}</figcaption> : null}
              </figure>
            ))}
          </div>
        </section>
      ) : null}

      {m.howToUse.length > 0 || m.commands.length > 0 ? (
        <section className="cw-section">
          <SectionHead eyebrow="Use it" title="How it works in the game" />
          <div className="cw-split">
            {m.howToUse.length > 0 ? <ol className="cw-steps">{m.howToUse.map((s, i) => <li key={i}>{s}</li>)}</ol> : <span />}
            {m.commands.length > 0 ? (
              <table className="cw-table">
                <thead><tr><th>Command</th><th>What it does</th></tr></thead>
                <tbody>{m.commands.slice(0, 12).map((x, i) => <tr key={i}><td><code className="cw-code">{x.usage}</code></td><td>{x.description}</td></tr>)}</tbody>
              </table>
            ) : null}
          </div>
        </section>
      ) : null}

      <section className="cw-section">
        <SectionHead eyebrow="Honest status" title="What was checked, and what was not" />
        <div className="cw-card" style={{ padding: 18 }}>
          <ul className="cw-fine" style={{ gap: 8, fontSize: 14, color: "var(--cx-ink-2)" }}>
            <li><Check ok={m.flight === "passed"} /> {m.flight === "passed" ? (m.flightLabel ?? "Boot-tested on Paper") + ". This checks that it starts and registers its commands, not every behaviour in play." : "No Test Flight result is recorded for this version."}</li>
            {m.flightLines.slice(0, 4).map((l, i) => <li key={i}><Check ok /> {l}</li>)}
            <li><Check ok={m.tested.earned} /> {m.tested.earned ? "Community-tested: enough other accounts run it, with good ratings and no open bugs." : `Community-tested not earned yet (${m.tested.passed} of ${m.tested.total} checks).`}</li>
            {m.assetLines.map((l, i) => <li key={`a${i}`}><Check ok /> {l}</li>)}
            {m.limitations.map((l, i) => <li key={`l${i}`}><Check ok={false} /> {l}</li>)}
          </ul>
        </div>
      </section>

      {m.versions.length > 0 ? (
        <section className="cw-section">
          <SectionHead eyebrow="Versions" title={`${m.versions.length} version${m.versions.length === 1 ? "" : "s"}`} />
          <table className="cw-table">
            <thead><tr><th>Version</th><th>Minecraft</th><th>Date</th><th>What changed</th></tr></thead>
            <tbody>{m.versions.map((v, i) => <tr key={i}><td>{v.version ? `v${v.version.replace(/^v/i, "")}` : "n/a"}{v.current ? " (current)" : ""}</td><td>{v.mcVersion}</td><td>{day(v.at)}</td><td>{clip(flat(v.notes), 200)}</td></tr>)}</tbody>
          </table>
        </section>
      ) : null}

      <section className="cw-cta-band">
        <div>
          <h2>Run it on a Nxeon server</h2>
          <p className="cx-sub" style={{ margin: "6px 0 0" }}>
            {coupon ? <>Use code <b>{coupon.code}</b>: {coupon.headline}. </> : null}Minecraft hosting, with Cyrus mods one click away.
          </p>
        </div>
        <a className="cx-btn cx-btn-energy" href={c.href("/host/minecraft")}><NxeonLogo height={16} /> See Minecraft hosting</a>
      </section>

      <section className="cw-section cw-faq">
        <SectionHead eyebrow="Questions" title="Quick answers" />
        {faq.map((f, i) => <details key={i}><summary>{f.q}</summary><p>{f.a}</p></details>)}
      </section>
      {m.flight === null && m.versions.length === 0 ? <Quiet>This page has no version details yet.</Quiet> : null}
    </>
  );
}
