// Server side of the Cyrus game status overrides (see lib/cyrus/game-status.ts for the rules).
// Plain module: safe in the worker. A DB error falls back to the file defaults.
import { CYRUS_GAMES } from "./games";
import { applyGameStatusOverrides, gameBuildable, gameStatusKey, type EffectiveGame } from "./game-status";
import { getHost } from "./host";

let cache: { at: number; games: EffectiveGame[] } | null = null;

export async function loadCyrusGameStatuses(fresh = false): Promise<EffectiveGame[]> {
  if (!fresh && cache && Date.now() - cache.at < 30_000) return cache.games;
  let stored: Record<string, string> = {};
  try {
    stored = await getHost().settings.readStored(CYRUS_GAMES.map((g) => gameStatusKey(g.id)));
  } catch {
    stored = {};
  }
  const games = applyGameStatusOverrides(CYRUS_GAMES, stored);
  cache = { at: Date.now(), games };
  return games;
}

export function clearCyrusGameStatusCache() {
  cache = null;
}

/** May a NEW build start for this game? (Minecraft only has a real pipeline today.) */
export async function cyrusGameBuildable(gameId: string): Promise<boolean> {
  return gameBuildable(await loadCyrusGameStatuses(), gameId);
}
