  const g = games.find((x) => x.id === game);
  if (!g || !c.contentOn) return { title: "Page not found", robots: { index: false, follow: false } };
  const live = gameBuildable(games, g.id);
  return webMetadata(c, {
    path: `/games/${g.id}`, surface: "content",
