    want: live,
    title: live ? `${g.name} mods and plugins made with Cyrus` : `${g.name}: coming soon to Cyrus`,
    description: live
      ? `Describe a ${g.name} plugin and Cyrus builds it for ${g.loader}${g.versions.length ? ` (${versionRange(g)})` : ""}. Browse mods made with Cyrus and install them on your server in one click.`
