// Everything one /host page needs, assembled from real data (SERVER ONLY). Pages render only what is in this object.
import { loadCoupon, loadHostCatalog, loadIndexPolicy, loadTokenFacts } from "./hosting.server";
import { faqJsonLd, hostCopy, hostFaq, resolveHost, routeIndexable, type CouponFacts, type HostCatalog, type HostCopy, type HostFaq, type HostRoute, type TokenFacts, type IndexPolicyInput } from "./hosting";

export type HostPageData = {
  route: NonNullable<HostRoute>;
  cat: HostCatalog;
  copy: HostCopy;
  coupon: CouponFacts | null;
  tokens: TokenFacts | null;
  faq: HostFaq[];
  faqLd: ReturnType<typeof faqJsonLd>;
  policy: IndexPolicyInput;
  /** passes the thin-page guard (the page may still be noindex when the owner has indexing off) */
  worthIndexing: boolean;
};

/** null = no such page (404). A game with no active plan, or a place with no enabled node, is not a page. */
export async function loadHostPage(a?: string | null, b?: string | null): Promise<HostPageData | null> {
  const [cat, coupon, policy] = await Promise.all([loadHostCatalog(), loadCoupon().catch(() => null), loadIndexPolicy()]);
  const route = resolveHost(cat, a, b);
  if (!route) return null;
  const game = route.kind === "game" || route.kind === "combo" ? route.game : null;
  const tokens = game ? await loadTokenFacts(game) : null;
  const faq = hostFaq(route, cat, { coupon, tokens });
  // worthIndexing ignores the owner's switch (policy.indexingOn) so the page can tell the admin what a flip would do
  const worthIndexing = routeIndexable(route, cat, { ...policy, indexingOn: true });
  return { route, cat, copy: hostCopy(route, cat), coupon, tokens, faq, faqLd: faqJsonLd(faq), policy, worthIndexing };
}
