// The Cyrus blog (cyrus.my/blog): a small typed content module, no CMS. PURE (the posts are data; the builders turn them
// into metadata, RSS and JSON-LD). Rules for every post: short (< 700 words), only what a real build or a real doc
// shows, numbers copied from the recorded runs, and an explicit "what we have not checked" where it applies.
// Tests: test/cyrus-content.test.ts (word counts, link targets, RSS, no invented-claim words).
import type { BlogCover } from "./art";

export type Block =
  | { t: "p"; text: string }
  | { t: "h2"; text: string }
  | { t: "ul"; items: string[] }
  | { t: "ol"; items: string[] }
  | { t: "pre"; text: string }
  | { t: "callout"; text: string }
  | { t: "img"; src: string; alt: string; caption: string; w: number; h: number }
  | { t: "table"; head: string[]; rows: string[][] };

export type Post = {
  slug: string;
  title: string;
  description: string;
  /** ISO date (UTC). */
  date: string;
  updated?: string;
  cover: BlogCover;
  coverAlt: string;
  tags: string[];
  blocks: Block[];
  /** slugs of related posts (the page also falls back to the newest others). */
  related?: string[];
};

export const BLOG_AUTHOR = { name: "The Cyrus team", official: true } as const;

/** Inline text: **bold**, `code`, [label](/path or https://...). Anything else is plain text. */
export type Inline = { k: "text" | "b" | "code"; v: string } | { k: "a"; v: string; href: string };
const TOKEN = /(\*\*[^*]+\*\*|`[^`]+`|\[[^\]]+\]\([^)\s]+\))/g;
export const safeHref = (h: string) => /^\/(?!\/)[A-Za-z0-9/_\-.?=&#%]*$/.test(h) || /^https:\/\/[A-Za-z0-9.-]+(?:\/[A-Za-z0-9/_\-.?=&#%]*)?$/.test(h);

export function parseInline(s: string): Inline[] {
  const out: Inline[] = [];
  for (const part of s.split(TOKEN)) {
    if (!part) continue;
    let m: RegExpExecArray | null;
    if (part.startsWith("**") && part.endsWith("**") && part.length > 4) out.push({ k: "b", v: part.slice(2, -2) });
    else if (part.startsWith("`") && part.endsWith("`") && part.length > 2) out.push({ k: "code", v: part.slice(1, -1) });
    else if ((m = /^\[([^\]]+)\]\(([^)\s]+)\)$/.exec(part))) out.push(safeHref(m[2]) ? { k: "a", v: m[1], href: m[2] } : { k: "text", v: m[1] });
    else out.push({ k: "text", v: part });
  }
  return out;
}

const plain = (s: string) => parseInline(s).map((i) => i.v).join("");
export function blockText(b: Block): string {
  switch (b.t) {
    case "p": case "h2": case "callout": return plain(b.text);
    case "pre": return b.text;
    case "ul": case "ol": return b.items.map(plain).join(" ");
    case "img": return b.caption;
    case "table": return [...b.head, ...b.rows.flat()].join(" ");
  }
}
export const wordCount = (p: Post) => p.blocks.map(blockText).join(" ").split(/\s+/).filter(Boolean).length;
export const readingMinutes = (p: Post) => Math.max(1, Math.round(wordCount(p) / 200));

export const sortedPosts = (posts: Post[]) => [...posts].sort((a, b) => b.date.localeCompare(a.date) || a.slug.localeCompare(b.slug));
export const postBySlug = (posts: Post[], slug: string) => posts.find((p) => p.slug === slug) ?? null;

export function relatedPosts(posts: Post[], p: Post, n = 3): Post[] {
  const named = (p.related ?? []).map((s) => postBySlug(posts, s)).filter((x): x is Post => !!x && x.slug !== p.slug);
  const rest = sortedPosts(posts).filter((x) => x.slug !== p.slug && !named.includes(x));
  return [...named, ...rest].slice(0, n);
}

// ── feeds and structured data ───────────────────────────────────────────────

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
const rfc822 = (iso: string) => new Date(iso).toUTCString();

export function rssXml(origin: string, posts: Post[], now = new Date()): string {
  const items = sortedPosts(posts).map((p) => {
    const url = `${origin}/blog/${p.slug}`;
    return `    <item>\n      <title>${esc(p.title)}</title>\n      <link>${esc(url)}</link>\n      <guid isPermaLink="true">${esc(url)}</guid>\n      <pubDate>${rfc822(p.date)}</pubDate>\n      <description>${esc(p.description)}</description>\n      <author>${esc(`blog@${new URL(origin).hostname} (${BLOG_AUTHOR.name})`)}</author>\n    </item>`;
  });
  const last = sortedPosts(posts)[0]?.date ?? now.toISOString();
  return `<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">\n  <channel>\n    <title>Cyrus blog</title>\n    <link>${esc(origin)}/blog</link>\n    <description>Builds, results and honest limits from the Cyrus team.</description>\n    <language>en</language>\n    <lastBuildDate>${rfc822(last)}</lastBuildDate>\n    <atom:link href="${esc(origin)}/blog/rss.xml" rel="self" type="application/rss+xml" />\n${items.join("\n")}\n  </channel>\n</rss>\n`;
}

export function articleJsonLd(origin: string, p: Post) {
  const url = `${origin}/blog/${p.slug}`;
  return {
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    headline: p.title,
    description: p.description,
    url,
    mainEntityOfPage: url,
    datePublished: p.date,
    dateModified: p.updated ?? p.date,
    wordCount: wordCount(p),
    inLanguage: "en",
    image: [`${origin}/cyrus/web/${p.cover}.jpg`],
    author: { "@type": "Organization", name: "Cyrus team", url: origin },
    publisher: { "@type": "Organization", name: "Cyrus", url: origin },
    keywords: p.tags.join(", "),
  };
}

export function blogIndexJsonLd(origin: string, posts: Post[]) {
  return {
    "@context": "https://schema.org",
    "@type": "Blog",
    name: "Cyrus blog",
    url: `${origin}/blog`,
    blogPost: sortedPosts(posts).map((p) => ({ "@type": "BlogPosting", headline: p.title, url: `${origin}/blog/${p.slug}`, datePublished: p.date })),
  };
}

