import type { Metadata } from "next";
import { POSTS } from "@/lib/cyrus-site/blog-posts";
import { blogIndexJsonLd, readingMinutes, sortedPosts } from "@/lib/cyrus-site/blog";
import { JsonLd } from "@/components/cyrus/web/parts";
import { requireContent, webCtx, webMetadata } from "../_ctx";

export const dynamic = "force-dynamic";

export async function generateMetadata(): Promise<Metadata> {
  const c = await webCtx();
  return webMetadata(c, {
    path: "/blog", surface: "content", want: true,
    title: "Cyrus blog: builds, results and honest limits",
    description: "What Cyrus built, what broke, and what it cannot do yet. Short posts with real results.",
    image: "/cyrus/web/og-blog.jpg",
  });
