    <>
      <JsonLd items={[blogIndexJsonLd(c.origin, posts)]} />
      <h1 className="cx-h1">Blog</h1>
      <p className="cx-sub">What Cyrus built, what broke, and what it cannot do yet. Short posts, real results.</p>
      <div className="cw-posts" style={{ marginTop: 22 }}>
        {posts.map((p) => (
          <a key={p.slug} className="cw-card cw-post" href={c.href(`/blog/${p.slug}`)}>
