/**
 * Create (or update) the CYRUS discount code that the cyrus.my /host pages advertise. DRY RUN unless --apply.
 *
 * Why this exists: on 2026-10-15 no Coupon with the code CYRUS (nor any partner code CYRUS) exists in the database, so the
 * hosting pages show NO discount block. The block appears by itself, with exactly the terms below, once this coupon
 * exists and is active (lib/cyrus-site/hosting.ts couponFacts reads the row; it never states anything the row does not say).
 * The owner decides the terms; nothing here has a default percentage.
 *
 * Usage (run on the primary node from a merged checkout; reads DATABASE_URL from the environment):
 *   set -a; . /opt/nxeon/.env; set +a
 *   NODE_PATH=/opt/nxeon/node_modules /opt/nxeon/node_modules/.bin/tsx scripts/cyrus/create-cyrus-coupon.ts \
 *       --percent 20 [--months 1] [--first-time] [--max 500] [--expires 2027-01-31] [--code CYRUS] [--apply]
 *
 *   --percent N     required, 1..100 (PERCENT coupon)
 *   --cents N       alternative to --percent: N cents off (FIXED_CENTS)
 *   --months N      discount only the first N months of a term (default 1: a 12-month order cannot become a year of discount)
 *   --first-time    only accounts that never had a paid server
 *   --max N         total redemptions across everyone (default: unlimited)
 *   --expires DATE  last day (UTC)
 *   --code C        default CYRUS (also the Setting cyrus_host_coupon_code the pages read)
 *
 * Scope is fixed: serviceKind GAME, scope ORDER (a game-server checkout, never wallet top-ups, never VPS).
 * One use per account and per IP is enforced by the existing redemption rows (lib/coupon-redemption.ts).
 */
import { db } from "../../lib/db";
import { couponFacts } from "../../lib/cyrus-site/hosting";

const arg = (n: string) => { const i = process.argv.indexOf(`--${n}`); return i > 0 ? process.argv[i + 1] : undefined; };
const has = (n: string) => process.argv.includes(`--${n}`);

async function main() {
  const code = (arg("code") ?? "CYRUS").trim().toUpperCase();
  if (!/^[A-Z0-9_-]{2,32}$/.test(code)) throw new Error("bad --code");
  const percent = arg("percent") ? Number(arg("percent")) : null;
  const cents = arg("cents") ? Number(arg("cents")) : null;
  if ((percent === null) === (cents === null)) throw new Error("give exactly one of --percent N or --cents N");
  if (percent !== null && !(Number.isInteger(percent) && percent >= 1 && percent <= 100)) throw new Error("--percent must be an integer 1..100");
  if (cents !== null && !(Number.isInteger(cents) && cents >= 1 && cents <= 1_000_000)) throw new Error("--cents must be a positive integer");
  const months = arg("months") ? Number(arg("months")) : 1;
  if (!(Number.isInteger(months) && months >= 1 && months <= 36)) throw new Error("--months must be 1..36");
  const max = arg("max") ? Number(arg("max")) : null;
  if (max !== null && !(Number.isInteger(max) && max >= 1)) throw new Error("--max must be a positive integer");
  const expiresAt = arg("expires") ? new Date(`${arg("expires")}T23:59:59.000Z`) : null;
  if (expiresAt && Number.isNaN(expiresAt.getTime())) throw new Error("--expires must be YYYY-MM-DD");

  const data = {
    kind: percent !== null ? ("PERCENT" as const) : ("FIXED_CENTS" as const),
    value: percent ?? (cents as number),
    scope: "ORDER" as const,
    serviceKind: "GAME" as const,
    planSlug: null,
    maxTermMonths: months,
    firstTimeOnly: has("first-time"),
    excludeActiveCustomers: false,
    minAmountCents: null,
    maxRedemptions: max,
    expiresAt,
    active: true,
    note: "Cyrus x Nxeon hosting cross-sell code (cyrus.my /host pages). Created by scripts/cyrus/create-cyrus-coupon.ts.",
  };
  const existing = await db.coupon.findUnique({ where: { code }, select: { id: true, kind: true, value: true, timesRedeemed: true, active: true } });
  const facts = couponFacts({ ...data, code, timesRedeemed: existing?.timesRedeemed ?? 0, trialDays: null }, new Date());
  console.log(existing ? `Existing coupon ${code}: ${existing.kind} ${existing.value}, redeemed ${existing.timesRedeemed}, active=${existing.active} -> will be UPDATED` : `No coupon ${code} yet -> will be CREATED`);
  console.log(JSON.stringify({ code, ...data, expiresAt: expiresAt?.toISOString() ?? null }, null, 2));
  console.log("The pages will say:", facts ? `${facts.code}: ${facts.headline}. ${facts.fineprint.join(" ")}` : "(nothing: these terms are not describable)");
  if (!has("apply")) { console.log("\nDRY RUN. Add --apply to write it."); return; }
  const c = await db.coupon.upsert({ where: { code }, update: data, create: { code, ...data } });
  console.log(`\nDone: ${c.code} ${c.kind} ${c.value}, first ${c.maxTermMonths} month(s), active=${c.active}.`);
}

main().then(() => process.exit(0)).catch((e) => { console.error(String(e?.message ?? e)); process.exit(1); });
EOF
