// Publish REAL, Cyrus-built mods under the Cyrus team's name and make them staff picks. DRY RUN unless --apply.
//
// Honest seeding (docs/cyrus/20-content.md): the public pages must not look empty at launch, but they must never be filled
// with invented creators, ratings or counters. This script only takes mods that already exist as CyrusModPage rows (built
// by Cyrus on the team's own account: the owner batch, the dungeon builds), refuses anything whose Test Flight failed or
// whose page has no real summary, and changes exactly these things:
//   1. CyrusModPage.visibility -> PUBLIC (the same field the creator's own Publish button sets)
//   2. a staff-pick entry per mod in Setting cyrus_spotlight_picks, with a reason made ONLY from recorded facts
//   3. the account id in Setting cyrus_official_user_ids (the "Made by the Cyrus team" badge)
//   4. optional --author-tag: the account's public author tag (CyrusCreator.username; staff may set a reserved word)
// It never writes a view, a rating, a star or an install. Counters stay at zero and the pages say "New".
//
//   set -a; . /opt/nxeon/.env; set +a
//   NODE_PATH=/opt/nxeon/node_modules /opt/nxeon/node_modules/.bin/tsx scripts/cyrus/seed-official-mods.ts \
//       --user <accountId> --slugs shop,quests,customrecipes [--week shop] [--author-tag cyrus] [--apply]
//
// The prod facts it relies on (read-only counts, 2026-10-15): 26 CyrusModPage rows, 2 PUBLIC, 24 PRIVATE, 0 hidden.
import { cyrusDb } from "../../lib/cyrus/db";
import { db } from "../../lib/db";
import { readModDoc } from "../../lib/cyrus/mods/doc";
import { flightFailedVerdict } from "../../lib/cyrus/app/failure";
import { OFFICIAL_KEY, parseOfficialIds } from "../../lib/cyrus-site/official";
import { SPOTLIGHT_KEY, parseSpotlight, upsertPick, validatePick, cleanReason, type SpotlightPick } from "../../lib/cyrus-site/spotlight";
import { validateUsername } from "../../lib/cyrus-mods/username";

const argv = process.argv.slice(2);
const opt = (n: string) => { const i = argv.indexOf(`--${n}`); return i >= 0 ? argv[i + 1] : undefined; };
const apply = argv.includes("--apply");

const slugs = (opt("slugs") ?? "").split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
const userId = opt("user") ?? "";
const weekSlug = opt("week");
const tag = opt("author-tag");

/** A reason line built only from what was recorded about this version. */
function reasonFor(title: string, d: NonNullable<ReturnType<typeof readModDoc>>): string {
  const bits: string[] = [];
  if (d.testFlight?.verdict === "passed") bits.push(d.testFlight.label ?? "boot-tested on Paper");
  if (d.commands.length) bits.push(`${d.commands.length} command${d.commands.length === 1 ? "" : "s"}`);
  if (d.assets?.textures?.length) bits.push(`${d.assets.textures.length} custom texture${d.assets.textures.length === 1 ? "" : "s"}`);
  if (d.assets?.sounds?.length) bits.push(`${d.assets.sounds.length} custom sound${d.assets.sounds.length === 1 ? "" : "s"}`);
  return cleanReason(`Built by the Cyrus team from one request${bits.length ? `: ${bits.join(", ")}` : ""}.`) || `${title}, built with Cyrus.`;
}

async function main() {
  if (!userId || slugs.length === 0) throw new Error("usage: --user <accountId> --slugs a,b,c [--week slug] [--author-tag name] [--apply]");
  const account = await db.user.findUnique({ where: { id: userId }, select: { id: true } });
  if (!account) throw new Error("no such account");
  if (tag) {
    // staff may use a reserved word (cyrus/team) for the official account; shape rules still apply
    const v = validateUsername(tag);
    if (!v.ok && v.code !== "reserved" && v.code !== "impersonation") throw new Error(`--author-tag: ${v.message}`);
  }
  const pages = await cyrusDb.cyrusModPage.findMany({ where: { slug: { in: slugs } } });
  const now = new Date();
  const picks: SpotlightPick[] = [];
  const toPublish: string[] = [];
  console.log(`Account ${userId}; ${slugs.length} slug(s) requested; ${apply ? "APPLY" : "dry run"}\n`);
  for (const slug of slugs) {
    const p = pages.find((x) => x.slug === slug);
    if (!p) { console.log(`SKIP  ${slug}: no such page`); continue; }
    if (p.userId !== userId) { console.log(`SKIP  ${slug}: owned by another account`); continue; }
    if (p.hiddenAt) { console.log(`SKIP  ${slug}: taken down by moderation (${p.hiddenReason ?? "no reason"})`); continue; }
    const d = readModDoc(p.doc);
    if (!d) { console.log(`SKIP  ${slug}: page document unreadable`); continue; }
    if (flightFailedVerdict(d.testFlight)) { console.log(`SKIP  ${slug}: Test Flight FAILED for the current version`); continue; }
    if ((d.summary?.trim().length ?? 0) < 120) { console.log(`SKIP  ${slug}: no real summary yet (needs >= 120 chars; open the page in Cyrus once to regenerate)`); continue; }
    const kind = weekSlug === slug ? "week" : "staff";
    const v = validatePick({ id: p.id, kind, reason: reasonFor(p.title, d), order: kind === "week" ? 0 : 10 + picks.length, startsAt: now.toISOString() }, now);
    if (!v.ok) { console.log(`SKIP  ${slug}: ${v.error}`); continue; }
    picks.push(v.pick);
    if (p.visibility !== "PUBLIC") toPublish.push(p.id);
    console.log(`OK    ${slug}: "${p.title}" v${p.latestVersion} | ${d.testFlight?.verdict ?? "no flight"} | ${p.visibility} -> PUBLIC | ${kind}: ${v.pick.reason}`);
  }
  if (!picks.length) { console.log("\nNothing to do."); return; }
  if (!apply) { console.log(`\nDRY RUN: ${picks.length} mod(s) would be made public + picked${tag ? `, author tag "${tag}"` : ""}. Add --apply to write.`); return; }

  let list = parseSpotlight((await db.setting.findUnique({ where: { key: SPOTLIGHT_KEY } }))?.value);
  for (const pk of picks) { const r = upsertPick(list, pk); if (!r.ok) throw new Error(r.error); list = r.list; }
  await db.setting.upsert({ where: { key: SPOTLIGHT_KEY }, update: { value: JSON.stringify(list) }, create: { key: SPOTLIGHT_KEY, value: JSON.stringify(list) } });
  const off = [...new Set([...parseOfficialIds((await db.setting.findUnique({ where: { key: OFFICIAL_KEY } }))?.value), userId])];
  await db.setting.upsert({ where: { key: OFFICIAL_KEY }, update: { value: JSON.stringify(off) }, create: { key: OFFICIAL_KEY, value: JSON.stringify(off) } });
  if (toPublish.length) await cyrusDb.cyrusModPage.updateMany({ where: { id: { in: toPublish } }, data: { visibility: "PUBLIC", publishedAt: now } });
  if (tag) {
    const key = tag.toLowerCase();
    const cur = await cyrusDb.cyrusCreator.findUnique({ where: { userId } });
    if (cur) await cyrusDb.cyrusCreator.update({ where: { userId }, data: { username: tag, usernameKey: key, usernameSetAt: now } });
    else await cyrusDb.cyrusCreator.create({ data: { userId, handle: key, username: tag, usernameKey: key, usernameSetAt: now } });
  }
  await db.auditLog.create({ data: { userId, action: "cyrus.content.seed", detail: `official seed: ${picks.length} mods, published ${toPublish.length}${tag ? `, tag ${tag}` : ""}`.slice(0, 900) } }).catch(() => {});
  console.log(`\nDone: ${toPublish.length} published, ${picks.length} picks, account marked official${tag ? `, author tag "${tag}"` : ""}.`);
}

main().then(() => process.exit(0)).catch((e) => { console.error(String(e?.message ?? e)); process.exit(1); });
EOF
