describe("hosting: the thin-page guard", () => {
  const on = { indexingOn: true, allowFamilies: [] as string[] };
  it("only games Cyrus builds for (or the owner allowed) are indexable; the rest render noindex and stay out of the sitemap", () => {
    const c = catalog();
    const paths = hostIndexablePaths(c, on);
    assert.ok(paths.includes("/host") && paths.includes("/host/minecraft") && paths.includes("/host/minecraft/singapore") && paths.includes("/host/germany"));
    assert.ok(!paths.some((p) => p.includes("valheim")), "valheim has no Cyrus value: not indexed");
    assert.deepEqual(hostIndexablePaths(c, { indexingOn: true, allowFamilies: ["valheim"] }).filter((p) => p.includes("valheim")).sort(), ["/host/valheim", "/host/valheim/canada", "/host/valheim/france", "/host/valheim/germany", "/host/valheim/singapore"]);
    assert.deepEqual(hostIndexablePaths(c, { indexingOn: false, allowFamilies: [] }), [], "owner's switch off = nothing listed");
  });
  it("route level agrees with the sitemap list", () => {
    const c = catalog();
    const vh = c.games.find((g) => g.family === "valheim")!;
    assert.ok(!gameIndexable(vh, on));
    assert.ok(!routeIndexable({ kind: "game", game: vh }, c, on));
    assert.ok(routeIndexable(resolveHost(c, "minecraft", "germany") as NonNullable<HostRoute>, c, on));
    assert.ok(!routeIndexable(resolveHost(c, "minecraft") as NonNullable<HostRoute>, c, { ...on, indexingOn: false }));
  });
  it("no locations (no enabled node) = no hub in the index", () => {
    const c = { ...catalog(), locations: [] };
    assert.ok(!routeIndexable({ kind: "hub" }, c, on));
    assert.deepEqual(hostIndexablePaths(c, on).filter((p) => p.split("/").length > 3), []);
  });
});

