describe("hosting: the token block quotes the ledger's own formula", () => {
  const live = parseTokenConfig({ cyrus_tok_live: "true" });
  const off = parseTokenConfig({});
  const mc = catalog().games.find((g) => g.family === "minecraft")!;
  const vh = catalog().games.find((g) => g.family === "valheim")!;
  it("off until the token economy is live", () => {
    assert.equal(off.live, false);
    assert.equal(tokenFacts(off, mc), null);
  });
  it("live: equals serverGrant for the cheapest plan (default settings: 718 cents -> 215 on purchase, 70 per renewal)", () => {
    const t = tokenFacts(live, mc)!;
    assert.equal(t.initial, serverGrant("initial", 718, 1, live).tokens);
    assert.equal(t.renewal, serverGrant("renewal", 718, 1, live).tokens);
    assert.equal(t.initial, 215);
    assert.equal(t.renewal, 70);
    assert.equal(t.basis.planName, "Minecraft 2 GB");
    assert.equal(t.perServerCap, live.grant.perServerCap);
  });
  it("only games the scope covers: default scope is cyrus_games, so Valheim earns nothing", () => {
    assert.equal(live.grant.scope, "cyrus_games");
    assert.equal(tokenFacts(live, vh), null);
    assert.ok(grantApplies("all_game_servers", "valheim", false));
    assert.ok(!grantApplies("cyrus_games", "valheim", false));
    assert.ok(tokenFacts(parseTokenConfig({ cyrus_tok_live: "true", cyrus_tok_grant_scope: "all_game_servers" }), vh));
  });
  it("a tuned setting changes the page, nothing is hard-coded", () => {
    const tuned = parseTokenConfig({ cyrus_tok_live: "true", cyrus_tok_grant_initial_base: "200", cyrus_tok_grant_initial_max: "900" });
    assert.ok(tokenFacts(tuned, mc)!.initial > 215);
  });
});

describe("hosting: copy and FAQ never claim latency, uptime or players", () => {
  const c = catalog();
  const all = () => {
    const routes: NonNullable<HostRoute>[] = [{ kind: "hub" }, ...c.games.map((g) => ({ kind: "game", game: g }) as const), ...c.locations.map((l) => ({ kind: "location", loc: l }) as const), { kind: "combo", game: c.games[0], loc: c.locations[0] }];
    return routes;
  };
  it("titles stay short, prices come from the plan, mod claims only for Cyrus games", () => {
    for (const r of all()) {
      const cp = hostCopy(r, c);
