// ── honesty guards over the source ──────────────────────────────────────────

function walk(dir: string, out: string[] = []): string[] {
  for (const n of readdirSync(dir)) {
    const p = path.join(dir, n);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(n)) out.push(p);
  }
  return out;
}

describe("honesty guards (source level)", () => {
  const files = [...walk(path.join(ROOT, "lib/cyrus-site")), ...walk(path.join(ROOT, "app/(cyrus-web)")), ...walk(path.join(ROOT, "components/cyrus/web")), path.join(ROOT, "app/api/cyrus/spotlight/route.ts")];
  const src = (f: string) => readFileSync(f, "utf8");
  it("nothing in the content engine writes a rating, star, install or invents a number", () => {
    for (const f of files) {
      const s = src(f);
      assert.doesNotMatch(s, /cyrusModRating\.(create|upsert|update)|cyrusModStar\.(create|upsert|update)|serverMod\.(create|upsert)/, f);
      assert.doesNotMatch(s, /Math\.random\(\)/, `${f}: no random numbers on public pages`);
      assert.doesNotMatch(s, /faker|lorem ipsum/i, f);
    }
  });
  it("the only writer of view counts is recordModView, and it is skipped for bots and the creator", () => {
    const writers = files.filter((f) => /cyrusModViewDay\.(create|upsert|update)/.test(src(f))).map((f) => path.relative(ROOT, f));
    assert.deepEqual(writers, ["lib/cyrus-site/views.ts"]);
    assert.match(src(path.join(ROOT, "lib/cyrus-site/views.ts")), /viewerIsCreator \|\| !isLikelyHuman/);
  });
  it("the seed script publishes existing pages and never writes counters", () => {
    const s = src(path.join(ROOT, "scripts/cyrus/seed-official-mods.ts"));
    assert.doesNotMatch(s, /cyrusModRating|cyrusModStar|cyrusModViewDay|cyrusModPage\.create|cyrusCreator\.create\(\{ data: \{ userId, handle: [^}]*views/);
    assert.match(s, /apply = argv\.includes\("--apply"\)/);
    assert.match(s, /flightFailedVerdict/);
  });
  it("the coupon script is a dry run by default and has no default discount", () => {
    const s = src(path.join(ROOT, "scripts/cyrus/create-cyrus-coupon.ts"));
    assert.match(s, /has\("apply"\)/);
    assert.match(s, /give exactly one of --percent/);
    assert.doesNotMatch(s, /percent\s*=\s*arg\("percent"\)\s*\?\s*Number\(arg\("percent"\)\)\s*:\s*\d/);
  });
  it("hosting pages read the coupon and the token settings, they do not hard-code a code, amount or price", () => {
    const host = [src(path.join(ROOT, "lib/cyrus-site/hosting.ts")), src(path.join(ROOT, "components/cyrus/web/HostView.tsx"))].join("\n");
    assert.doesNotMatch(host, /\$\d+\.\d\d|\b\d+% off|\bCYRUS\b[^_]/);
  });
  it("public pages are noindex unless the owner switches are on (metadata goes through webMetadata)", () => {
    for (const f of files.filter((x) => /app\/\(cyrus-web\)\/.*page\.tsx$/.test(x))) assert.match(src(f), /webMetadata|notFound/, f);
  });
});

