const ROOT = path.resolve(__dirname, "..");
const NOW = new Date("2026-10-15T12:00:00Z");

// ── paths ───────────────────────────────────────────────────────────────────

describe("content paths", () => {
  it("maps the public roots onto the internal tree and nothing else", () => {
    assert.equal(webPath("/games"), "/cyrus-web/games");
    assert.equal(webPath("/games/minecraft"), "/cyrus-web/games/minecraft");
    assert.equal(webPath("/mods"), "/cyrus-web/mods");
    assert.equal(webPath("/mods/shop-gui"), "/cyrus-web/mods/shop-gui");
    assert.equal(webPath("/host"), "/cyrus-web/host");
    assert.equal(webPath("/host/minecraft"), "/cyrus-web/host/minecraft");
    assert.equal(webPath("/host/minecraft/singapore"), "/cyrus-web/host/minecraft/singapore");
    assert.equal(webPath("/blog"), "/cyrus-web/blog");
    assert.equal(webPath("/blog/rss.xml"), "/cyrus-web/blog/rss.xml");
    for (const bad of ["/", "/hosting", "/host/a/b/c", "/mods/a/b", "/blog/x/y", "/mods/", "/mods/UPPER", "/mods/..%2f", "/mods/a b", "/games/x/y", "/blog/rss.xml/x"]) assert.equal(webPath(bad), null, bad);
  });
  it("slugs are lowercase url-safe", () => {
    assert.ok(isWebSlug("a1-b2"));
    for (const bad of ["", "-a", "A", "a_b", "a/b", "x".repeat(90), 5]) assert.ok(!isWebSlug(bad as unknown));
    assert.deepEqual([...WEB_ROOTS], ["games", "mods", "host", "blog"]);
  });
  it("links: public path on the Cyrus host, internal tree elsewhere", () => {
    assert.equal(webHref(true, "/mods/x"), "/mods/x");
    assert.equal(webHref(false, "/mods/x"), "/cyrus-web/mods/x");
  });
  it("the Cyrus host rewrites reads, 404s writes, and passes the internal tree", () => {
    const cfg = bridgeConfig({ CYRUS_DOMAIN_MODE: "1", CYRUS_HOSTS: "cyrus.my", APP_URL: "https://nxeon.cloud" });
    const g = (pathname: string, method = "GET") => cyrusHostRoute({ pathname, search: "", method, cfg });
    assert.deepEqual(g("/host/minecraft/singapore"), { kind: "rewrite", pathname: "/cyrus-web/host/minecraft/singapore" });
    assert.deepEqual(g("/blog/rss.xml"), { kind: "rewrite", pathname: "/cyrus-web/blog/rss.xml" });
    assert.deepEqual(g("/mods/x", "POST"), { kind: "notfound" });
