});

// ── spotlight ───────────────────────────────────────────────────────────────

const pick = (o: Partial<SpotlightPick> & { id: string }): SpotlightPick => ({ kind: "staff", reason: "A reason", order: 0, startsAt: null, endsAt: null, addedAt: "2026-10-01T00:00:00.000Z", ...o });

describe("spotlight: editorial, never a counter", () => {
  it("parses defensively: bad rows, duplicates, junk ids and empty reasons are dropped", () => {
    const raw = JSON.stringify([
      { id: "a", kind: "staff", reason: "ok" },
      { id: "a", kind: "staff", reason: "dup" },
      { id: "a", kind: "week", reason: "same mod, other kind is allowed" },
      { id: "../x", kind: "staff", reason: "bad id" },
      { id: "b", kind: "other", reason: "bad kind" },
      { id: "c", kind: "staff", reason: "   " },
      "junk", null,
    ]);
    assert.deepEqual(parseSpotlight(raw).map((p) => `${p.kind}:${p.id}`), ["staff:a", "week:a"]);
    assert.deepEqual(parseSpotlight("not json"), []);
    assert.deepEqual(parseSpotlight(null), []);
    assert.equal(parseSpotlight(JSON.stringify(Array.from({ length: 100 }, (_, i) => ({ id: `p${i}`, kind: "staff", reason: "r" })))).length, 60);
  });
  it("reasons are one clean line", () => {
    assert.equal(cleanReason("  a\n\t<b>b</b>  c "), "a b b /b c".replace("b /b", "b /b"));
    assert.equal(cleanReason("x".repeat(500)).length, 140);
    assert.equal(cleanReason(42), "");
  });
  it("a reason is required and a week pick always gets an end", () => {
    assert.equal(validatePick({ id: "p1", kind: "staff", reason: "" }, NOW).ok, false);
    assert.equal(validatePick({ id: "p1", kind: "nope", reason: "why" }, NOW).ok, false);
    const w = validatePick({ id: "p1", kind: "week", reason: "Best build of the week" }, NOW);
    assert.ok(w.ok);
    if (w.ok) {
      assert.equal(w.pick.startsAt, NOW.toISOString());
      assert.equal(new Date(w.pick.endsAt!).getTime() - NOW.getTime(), WEEK_DAYS * 86_400_000);
    }
    assert.equal(validatePick({ id: "p1", kind: "week", reason: "why", startsAt: "2026-10-20", endsAt: "2026-10-19" }, NOW).ok, false);
    const s = validatePick({ id: "p1", kind: "staff", reason: "why" }, NOW);
    assert.ok(s.ok && s.pick.startsAt === null && s.pick.endsAt === null);
  });
  it("windows: start <= now < end, a missing bound is open", () => {
    const p = pick({ id: "a", startsAt: "2026-10-16T00:00:00Z", endsAt: "2026-10-23T00:00:00Z" });
    assert.equal(pickState(p, NOW), "scheduled");
    assert.equal(pickState(p, new Date("2026-10-16T00:00:00Z")), "live");
    assert.equal(pickState(p, new Date("2026-10-23T00:00:00Z")), "ended");
    assert.ok(pickActive(pick({ id: "b" }), NOW));
  });
  it("selection: Mod of the week first, ordered, capped; the older featured list still shows as staff picks without a reason", () => {
    const picks = [
      pick({ id: "w2", kind: "week", order: 2, startsAt: "2026-10-14T00:00:00Z", endsAt: "2026-10-21T00:00:00Z" }),
      pick({ id: "w1", kind: "week", order: 1, startsAt: "2026-10-14T00:00:00Z", endsAt: "2026-10-21T00:00:00Z" }),
      pick({ id: "old", kind: "week", order: 0, startsAt: "2026-09-01T00:00:00Z", endsAt: "2026-09-08T00:00:00Z" }),
      pick({ id: "s2", order: 2 }), pick({ id: "s1", order: 1 }),
    ];
    const sel = selectSpotlight(picks, NOW, ["s1", "legacy", "w1"]);
    assert.equal(sel.modOfWeek?.id, "w1");
    assert.deepEqual(sel.thisWeek.map((p) => p.id), ["w1", "w2"]);
    assert.deepEqual(sel.staffPicks.map((p) => p.id), ["s1", "s2", "legacy"]);
    assert.equal(sel.staffPicks.find((p) => p.id === "legacy")!.reason, null);
    assert.ok(sel.thisWeek.length <= THIS_WEEK_MAX);
    assert.deepEqual(selectSpotlight([], NOW, []), { modOfWeek: null, thisWeek: [], staffPicks: [] });
  });
  it("upsert replaces the same kind+mod, remove is exact", () => {
    const a = pick({ id: "a", reason: "one" });
    const r = upsertPick([a], pick({ id: "a", reason: "two" }));
