  });
  it("components count only past their own threshold", () => {
    assert.equal(signalScore(s(SIGNAL_MIN.views7d, 0, 0)), Math.round(Math.log10(1 + SIGNAL_MIN.views7d) * 100) / 100);
    assert.equal(signalScore(s(0, SIGNAL_MIN.installers, 0)), 2 * SIGNAL_MIN.installers);
    // 4 five-star ratings do not count (below 5); 5 do: (5-3)*5/5 = 2
    assert.equal(signalScore(s(30, 0, 4, 5)), Math.round(Math.log10(31) * 100) / 100);
    assert.equal(signalScore(s(0, 0, 5, 5)), 2);
    assert.equal(signalScore(s(0, 0, 5, 2)), -1);
  });
  it('"Popular right now" needs at least three qualifying mods, else nothing', () => {
    const mk = (id: string, sig: ReturnType<typeof s>) => ({ id, signals: sig });
    assert.deepEqual(popularList([mk("a", s(50, 0, 0)), mk("b", s(60, 0, 0)), mk("c", s(1, 0, 0))]), []);
    assert.equal(POPULAR_MIN_MODS, 3);
