    assert.ok(!xml.includes("&nbsp;") && !/<title>[^<]*&[^a]/.test(xml.replace(/&amp;|&lt;|&gt;|&quot;|&apos;/g, "")));
    assert.match(xml, /<guid isPermaLink="true">https:\/\/cyrus\.my\/blog\/[a-z0-9-]+<\/guid>/);
    const ld = articleJsonLd("https://cyrus.my", POSTS[0]) as { author: { "@type": string }; image: string[]; wordCount: number };
