// Quality bar for indexing a public mod page (PURE). docs/cyrus/20-content.md.
/** Indexing quality bar (docs/cyrus/20-content.md): enough real text to be useful and a Test Flight that did not fail. */
export function modIndexable(d: { summary: string | null; commands: number; features: number; flight: "passed" | "failed" | null; hidden?: boolean }): boolean {
  if (d.hidden || d.flight === "failed") return false;
  return (d.summary?.trim().length ?? 0) >= 120 && d.commands + d.features >= 1;
}

