// Cyrus docs coverage (r46): keeps docs/cyrus LIVING. It fails when
//  - a Cyrus env flag / setting / route / DB table / adapter / game / registry version / OpenAPI operation exists in code
//    but is missing from the generated reference pages (docs/cyrus/reference/*),
//  - a generated page is stale (re-run: npx tsx scripts/cyrus/docs-build.ts),
//  - docs/cyrus/_data/features.json names a flag, branch-less doc or anchor that does not exist,
//  - a relative link in docs/cyrus is broken, a numbered page is missing from the README, or the admin viewer is gone,
//  - a secret-looking string or an IP address slipped into the docs.
// The detection here is deliberately a second, simpler implementation than the generator's, so a gap in one is caught by the other.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import { ADAPTERS } from "../lib/cyrus/adapters";
import { CYRUS_GAMES } from "../lib/cyrus/games";
import { ROOT, buildAll } from "../scripts/cyrus/docs-build";

const rd = (rel: string) => readFileSync(path.join(ROOT, rel), "utf8");
const SCAN = ["lib", "app", "components", "services", "worker", "scripts", "deploy", "platform", "apps", "tools"];
const SKIP = new Set(["node_modules", ".next", ".git", "test", "fixtures", "dist", "build"]);

function walk(rel: string, out: string[] = []): string[] {
  const abs = path.join(ROOT, rel);
  if (!existsSync(abs)) return out;
  if (statSync(abs).isFile()) { out.push(rel); return out; }
  for (const n of readdirSync(abs)) if (!SKIP.has(n) && !n.startsWith(".")) walk(rel + "/" + n, out);
  return out;
}
const codeFiles = SCAN.flatMap((r) => walk(r)).filter((f) => /\.(ts|tsx|js|mjs|cjs|sh|service)$/.test(f) && !/\.test\.tsx?$/.test(f) && !/\.d\.ts$/.test(f));

const REF = (n: string) => rd(`docs/cyrus/reference/${n}.md`);
const slug = (h: string) => h.trim().toLowerCase().replace(/[`*]/g, "").replace(/[^a-z0-9 _-]/g, "").replace(/ /g, "-");
function anchorsOf(rel: string): Set<string> {
  return new Set(rd(rel).split("\n").filter((l) => /^#{1,6} /.test(l)).map((l) => slug(l.replace(/^#{1,6} /, ""))));
}
function docFiles(dir = "docs/cyrus", out: string[] = []): string[] {
  for (const n of readdirSync(path.join(ROOT, dir))) {
    const p = dir + "/" + n;
    if (statSync(path.join(ROOT, p)).isDirectory()) docFiles(p, out);
    else if (n.endsWith(".md")) out.push(p);
  }
  return out;
}

describe("cyrus docs: generated references are complete", () => {
  const flags = REF("flags-and-env");

  it("every quoted CYRUS_* / MB_* flag in Cyrus code is in the flags reference", () => {
    const missing = new Set<string>();
    for (const f of codeFiles) {
      if (!/cyrus|modbuilder|mod-builder/i.test(f) && !/CYRUS_/.test(rd(f))) continue;
      if (f.startsWith("components/") || f.startsWith("tools/")) continue;
      const t = rd(f);
      for (const m of t.matchAll(/process\.env\.((?:CYRUS|MB)_[A-Z0-9_]+)|["'`]((?:CYRUS|MB)_[A-Z0-9_]+)["'`]/g)) {
        const n = m[1] ?? m[2];
        if (n.startsWith("MB_") && !/modbuilder|cyrus|deploy\/|scripts\//.test(f)) continue;
        if (!flags.includes("`" + n + "`")) missing.add(n + "  (" + f + ")");
      }
    }
    assert.deepEqual([...missing].sort(), [], "env flags missing from docs/cyrus/reference/flags-and-env.md: run npx tsx scripts/cyrus/docs-build.ts");
  });

