cd /tank/dev-worktrees/cyrus-content && cat > scripts/cyrus/content-shots.mjs <<'EOF'
// Cyrus content pages screenshots (run ON node-2 against `devhost dev`, after scripts/cyrus/content-fixtures.ts).
//   devhost run -- env BASE=http://127.0.0.1:<port> OUT=.shots/content node scripts/cyrus/content-shots.mjs
// Writes <OUT>/<name>-<1440|390>.png, prints status, horizontal overflow and page errors per shot.
import { createRequire } from "node:module";
import { mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots/content";
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
const VIEWS = [{ w: 1440, h: 900, mobile: false }, { w: 390, h: 844, mobile: true }];
const PAGES = [
  ["games", "/cyrus-web/games"], ["game-minecraft", "/cyrus-web/games/minecraft"], ["game-valheim-stub", "/cyrus-web/games/valheim"],
  ["mods", "/cyrus-web/mods"], ["mod-shop", "/cyrus-web/mods/shop"], ["mod-hollow-king", "/cyrus-web/mods/hollow-king"], ["mod-thin", "/cyrus-web/mods/thin-page"],
  ["host-hub", "/cyrus-web/host"], ["host-minecraft", "/cyrus-web/host/minecraft"], ["host-singapore", "/cyrus-web/host/singapore"],
  ["host-minecraft-singapore", "/cyrus-web/host/minecraft/singapore"], ["host-valheim-germany", "/cyrus-web/host/valheim/germany"],
  ["blog", "/cyrus-web/blog"], ["blog-post-dungeon", "/cyrus-web/blog/infinite-dungeon-what-it-built"], ["blog-post-limits", "/cyrus-web/blog/what-cyrus-cannot-do-yet"],
];
const LIGHT = new Set(["host-minecraft", "mod-shop"]);
const ONLY = process.env.SHOTS ? process.env.SHOTS.split(",") : null;
async function shot(name, url, v, theme) {
  const ctx = await browser.newContext({ viewport: { width: v.w, height: v.h }, deviceScaleFactor: v.mobile ? 2 : 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 200)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 160)); });
  const res = await page.goto(BASE + url, { waitUntil: "load", timeout: 300000 }).catch((e) => { errs.push("goto " + e); return null; });
  await page.waitForSelector(".cw-main", { timeout: 60000 }).catch(() => errs.push("no .cw-main"));
  await page.waitForTimeout(1200);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  const robots = await page.evaluate(() => document.querySelector('meta[name="robots"]')?.getAttribute("content") ?? "").catch(() => "");
  const canon = await page.evaluate(() => document.querySelector('link[rel="canonical"]')?.getAttribute("href") ?? "").catch(() => "");
  await page.screenshot({ path: `${OUT}/${name}-${v.w}${theme === "light" ? "-light" : ""}.png`, fullPage: true, timeout: 120000 }).catch((e) => errs.push("shot " + String(e).slice(0, 100)));
  console.log(`${name}-${v.w}${theme === "light" ? "-light" : ""}`, res ? res.status() : "-", overflow > 1 ? `OVERFLOW ${overflow}px` : "ok", `robots=${robots || "-"}`, `canonical=${canon || "-"}`, errs.length ? "ERR " + errs.join(" | ").slice(0, 400) : "");
  await ctx.close();
}
for (const [name, url] of PAGES) {
  if (ONLY && !ONLY.some((o) => name.includes(o))) continue;
  for (const v of VIEWS) await shot(name, url, v, "dark");
  if (LIGHT.has(name)) await shot(name, url, VIEWS[0], "light");
}
await browser.close();
EOF
